class _A2R2PublicationOwnerResult(unittest.TestResult):
    """Retain structured subtest outcomes without using traceback text as keys."""

    def __init__(self) -> None:
        super().__init__()
        self.subtest_outcomes: list[dict[str, object]] = []
        self.top_level_failures: list[dict[str, object]] = []

    def addSubTest(self, test, subtest, outcome) -> None:
        parameters = tuple(dict(subtest.params).items())
        self.subtest_outcomes.append(
            {
                "case": test,
                "subtest": subtest,
                "key": (test._testMethodName, parameters),
                "outcome": outcome,
                "exception": None if outcome is None else outcome[1],
            }
        )
        super().addSubTest(test, subtest, outcome)

    def addFailure(self, test, outcome) -> None:
        self.top_level_failures.append(
            {
                "case": test,
                "outcome": outcome,
                "exception": outcome[1],
            }
        )
        super().addFailure(test, outcome)


def _policies(paths: Mapping[str, Path]) -> dict[str, proof_io.InputMetadataPolicy]:
    result: dict[str, proof_io.InputMetadataPolicy] = {}
    for label, path in paths.items():
        status = path.lstat()
        mode = stat.S_IMODE(status.st_mode) & ~0o022
        path.chmod(mode)
        status = path.lstat()
        result[label] = proof_io.InputMetadataPolicy(
            mode=mode,
            uid=status.st_uid,
            gid=status.st_gid,
            nlink=status.st_nlink,
        )
    return result


def _mount_fixture() -> tuple[bytes, dict[str, object]]:
    container_id = "a" * 64
    rootfs = "/store/vfs/dir/" + "b" * 64
    scratch = "/private/scratch"
    containerenv = (
        "/store/runroot/vfs-containers/" + container_id
        + "/userdata/.containerenv"
    )
    specification = {
        "root": {"path": rootfs, "readonly": True},
        "mounts": [
            {"destination": destination, "source": source}
            for destination, source in (
                ("/tmp", "tmpfs"), ("/proc", "proc"),
                ("/dev", "tmpfs"), ("/sys", "sysfs"),
                ("/tmp/work", scratch), ("/dev/pts", "devpts"),
                ("/dev/mqueue", "mqueue"), ("/dev/shm", "/static/shm"),
                ("/run/.containerenv", containerenv),
                ("/sys/fs/cgroup", "cgroup"),
            )
        ],
        "linux": {
            "maskedPaths": list(EXPECTED_MASKED_PATHS),
            "readonlyPaths": list(EXPECTED_READONLY_PATHS),
        },
    }
    uid = os.getuid()
    gid = os.getgid()
    records: list[tuple[int, int, str, str, str, str, str, str, str]] = []

    def add(
        identity: int,
        parent: int,
        device: str,
        root: str,
        target: str,
        options: str,
        filesystem: str,
        source: str,
        super_options: str,
    ) -> None:
        records.append(
            (identity, parent, device, root, target, options,
             filesystem, source, super_options)
        )

    add(100, 90, "259:6", rootfs, "/", "ro,relatime", "ext4", "/dev/disk", "rw")
    add(101, 100, "0:101", "/", "/tmp", "rw,nosuid,nodev,relatime", "tmpfs", "tmpfs", f"rw,uid={uid},gid={gid},inode64")
    add(102, 101, "259:6", scratch, "/tmp/work", "rw,nosuid,nodev,relatime", "ext4", "/dev/disk", "rw")
    add(103, 100, "0:103", "/", "/proc", "rw,nosuid,nodev,noexec,relatime", "proc", "proc", "rw")
    add(104, 100, "0:104", "/", "/dev", "ro,nosuid", "tmpfs", "tmpfs", f"rw,size=65536k,mode=755,uid={uid},gid={gid},inode64")
    add(105, 100, "0:105", "/", "/sys", "ro,nosuid,nodev,noexec,relatime", "sysfs", "sysfs", "rw")
    add(106, 104, "0:106", "/", "/dev/pts", "rw,nosuid,noexec,relatime", "devpts", "devpts", "rw,gid=100004,mode=620,ptmxmode=666")
    add(107, 104, "0:107", "/", "/dev/mqueue", "rw,nosuid,nodev,noexec,relatime", "mqueue", "mqueue", "rw")
    add(108, 104, "0:108", "/", "/dev/shm", "ro,nosuid,nodev,noexec,relatime", "tmpfs", "shm", f"rw,size=64000k,uid={uid},gid={gid},inode64")
    add(109, 100, "259:6", containerenv, "/run/.containerenv", "ro,nosuid,nodev,noexec,relatime", "ext4", "/dev/disk", "rw")
    add(110, 105, "0:110", f"/user.slice/user-{uid}.slice/user@{uid}.service/app.slice/{container_id}", "/sys/fs/cgroup", "ro,nosuid,nodev,noexec,relatime", "cgroup2", "cgroup2", "rw,nsdelegate,memory_recursiveprot,memory_hugetlb_accounting")
    dev_super = "rw,size=1000k,nr_inodes=2000,mode=755,inode64"
    next_id = 111
    for name in ("null", "zero", "full", "tty", "random", "urandom"):
        add(next_id, 104, "0:7", f"/{name}", f"/dev/{name}", "rw,nosuid,noexec", "devtmpfs", "devtmpfs", dev_super)
        next_id += 1
    for target, parent, root, device, filesystem, source, options, super_options in (
        ("/proc/acpi", 103, "/", "0:201", "tmpfs", "tmpfs", "ro,relatime", f"rw,size=0k,uid={uid},gid={gid},inode64"),
        ("/proc/kcore", 103, "/null", "0:7", "devtmpfs", "devtmpfs", "ro,nosuid", dev_super),
        ("/proc/keys", 103, "/null", "0:7", "devtmpfs", "devtmpfs", "ro,nosuid", dev_super),
        ("/proc/latency_stats", 103, "/null", "0:7", "devtmpfs", "devtmpfs", "ro,nosuid", dev_super),
        ("/proc/scsi", 103, "/", "0:202", "tmpfs", "tmpfs", "ro,relatime", f"rw,size=0k,uid={uid},gid={gid},inode64"),
        ("/proc/timer_list", 103, "/null", "0:7", "devtmpfs", "devtmpfs", "ro,nosuid", dev_super),
        ("/sys/devices/virtual/powercap", 105, "/", "0:203", "tmpfs", "tmpfs", "ro,relatime", f"rw,size=0k,uid={uid},gid={gid},inode64"),
        ("/sys/firmware", 105, "/", "0:204", "tmpfs", "tmpfs", "ro,relatime", f"rw,size=0k,uid={uid},gid={gid},inode64"),
        ("/proc/interrupts", 103, "/null", "0:7", "devtmpfs", "devtmpfs", "ro,nosuid", dev_super),
    ):
        add(next_id, parent, device, root, target, options, filesystem, source, super_options)
        next_id += 1
    first_powercap_id = next(
        item[0] for item in records
        if item[4] == "/sys/devices/virtual/powercap"
    )
    add(next_id, first_powercap_id, "0:205", "/", "/sys/devices/virtual/powercap", "ro,relatime", "tmpfs", "tmpfs", f"rw,size=0k,uid={uid},gid={gid},inode64")
    next_id += 1
    for target, root in (
        ("/proc/asound", "/asound"), ("/proc/bus", "/bus"),
        ("/proc/fs", "/fs"), ("/proc/irq", "/irq"),
        ("/proc/sys", "/sys"), ("/proc/sysrq-trigger", "/sysrq-trigger"),
    ):
        add(next_id, 103, "0:103", root, target, "ro,nosuid,nodev,noexec,relatime", "proc", "proc", "rw")
        next_id += 1
    raw = "".join(
        f"{identity} {parent} {device} {root} {target} {options} - "
        f"{filesystem} {source} {super_options}\n"
        for identity, parent, device, root, target, options,
        filesystem, source, super_options in records
    ).encode("ascii")
    return raw, specification


def _fixture_projection():
    from tools.gate01.oci_rootfs import OwnershipProjection
    return OwnershipProjection(
        uid_ranges=((0, os.getuid(), 1), (1, 100000, 65536)),
        gid_ranges=((0, os.getgid(), 1), (1, 100000, 65536)),
        allow_identity=False,
    )


