@lru_cache(maxsize=2)
def _fixture_normalization_ledger(root_values: tuple[tuple[str, int], ...], basename: str, parent_ino: int):
    """Complete cardinality, compactly reused immutable public fixture bytes."""
    from tools.gate01 import oci_rootfs
    root = dict(root_values)
    rows = {"/": oci_rootfs.RawEntry(path="/", name=basename, parent_dev=root["dev"], parent_ino=parent_ino, **root)}
    for index in range(138620):
        path = f"/fixture-{index:06d}"
        rows[path] = oci_rootfs.RawEntry(path=path, name=path[1:], parent_dev=root["dev"], parent_ino=root["ino"], dev=root["dev"], ino=1000000 + index, nlink=1, mode=stat.S_IFREG | 0o644, uid=0, gid=0, rdev=0, size=0, mtime_ns=0, ctime_ns=100)
    encoded = proof_io._json_safe(oci_rootfs._encode_normalization_ledger(rows))
    return encoded


def _fixture_event_multiset(events: list[dict[str, object]]) -> list[dict[str, object]]:
    counts = Counter(
        (event["watch"], event["mask"], event["cookie"], event["name"])
        for event in events
    )
    return [
        {"watch": watch, "mask": mask, "cookie": cookie, "name": name, "count": count}
        for (watch, mask, cookie, name), count in sorted(counts.items())
    ]


def _a3_runtime_input_binding(
    *,
    dev: int,
    uid: int,
    gid: int,
    sequence: int,
    config_stop: dict[str, object],
    initially_present: bool,
    middle_masks: tuple[int, ...] = (),
) -> tuple[dict[str, object], dict[str, object] | None]:
    def runtime_stat(
        ino: int,
        kind: int,
        mode: int,
        *,
        size: int = 0,
        mtime_ns: int = 100,
        ctime_ns: int = 100,
        nlink: int = 1,
    ) -> dict[str, int]:
        return {
            "dev": dev, "gid": gid, "ino": ino, "mode": mode,
            "mtime_ns": mtime_ns, "ctime_ns": ctime_ns, "nlink": nlink,
            "size": size, "type": kind, "uid": uid,
        }

    limits = {"max_event_bytes": 65536, "max_events": 1024, "max_middle_events": 16}
    pid = runtime_stat(sequence + 31, stat.S_IFREG, 0o644, size=4)
    parent_before = runtime_stat(sequence + 32, stat.S_IFDIR, 0o700, size=4096)
    parent_after_start = {**parent_before, "size": 8192, "ctime_ns": 101}
    parent_before_stop = {**parent_after_start, "ctime_ns": 102}
    parent_after_stop = {**parent_before_stop, "size": 4096, "ctime_ns": 103}
    pre_listing = [".containerenv", "conmon.pid"] if initially_present else [".containerenv"]
    post_listing = [".containerenv", "conmon.pid"]
    start_events = [] if initially_present else [
        {"cookie": 0, "mask": 256, "name": "conmon.pid", "watch": 2},
        *(
            {"cookie": 0, "mask": mask, "name": "conmon.pid", "watch": 2}
            for mask in middle_masks
        ),
        {"cookie": 0, "mask": 8, "name": "conmon.pid", "watch": 2},
    ]
    pid_delete = {"cookie": 0, "mask": 512, "name": "conmon.pid", "watch": 2}
    stop = copy.deepcopy(config_stop)
    outer_events = copy.deepcopy(stop["observed_events"])
    outer_events.insert(1, copy.deepcopy(pid_delete))
    stop["observed_events"] = outer_events
    stop["event_multiset"] = _fixture_event_multiset(outer_events)
    stop["reserved_lifecycle"] = {
        "initial": copy.deepcopy(pid),
        "start": {
            "initial_present": initially_present,
            "current_present": True,
            "limits": copy.deepcopy(limits),
            "target_before": copy.deepcopy(pid) if initially_present else None,
            "target_after": copy.deepcopy(pid),
            "pre_listing": pre_listing,
            "post_listing": list(post_listing),
            "pre_parent_metadata": copy.deepcopy(parent_before),
            "post_parent_metadata": parent_after_start,
            "observed_events": start_events,
            "event_multiset": _fixture_event_multiset(start_events),
            "state": "post-start",
        },
        "stop": {
            "current_present": False,
            "limits": copy.deepcopy(limits),
            "target_before": copy.deepcopy(pid),
            "target_after": {**pid, "nlink": 0, "ctime_ns": pid["ctime_ns"] + 1},
            "pre_listing": list(post_listing),
            "post_listing": [".containerenv"],
            "pre_parent_metadata": parent_before_stop,
            "post_parent_metadata": parent_after_stop,
            "observed_events": [copy.deepcopy(pid_delete)],
            "event_multiset": _fixture_event_multiset([pid_delete]),
            "state": "post-stop",
        },
    }
    watcher = {
        "basenames": {"config": "config.json", "containerenv": ".containerenv"},
        "coalesced_parent_watch_count": 2,
        "parent_fields_excluding_time": [
            "dev", "ino", "type", "mode", "uid", "gid", "nlink", "size"
        ],
        "persistent_parent_listing": "exact",
        "policy": "inotify-reserved-lifecycle-fail-closed-v1",
        "schema": "openmythos-runtime-input-binding-v2",
        "stop_projection": stop,
    }
    conmon_target = None
    if initially_present:
        conmon_target = {
            **{
                key: pid[key]
                for key in ("dev", "gid", "ino", "mode", "nlink", "type", "uid")
            },
            "present": True,
        }
    return watcher, conmon_target


def _runtime_evidence(
    repository: Path,
    builder: str,
    capsule: dict[str, object],
    *,
    probe_root: Path | None = None,
    normalization_audit=None,
    initially_present_by_role: Mapping[str, bool] | None = None,
) -> tuple[dict[str, object], dict[str, object]]:
    uid, gid = os.getuid(), os.getgid()
    if initially_present_by_role is None:
        initially_present_by_role = {"build": False, "inspection": False}
    rootfs = {"schema_version": 1, "expected": copy.deepcopy(capsule["oci_rootfs"])}
    contract = {"schema_version": 1, "key_scope": {"probe": False, "build": True, "inspection": False}, "stores_distinct": True, "repository_mounted": False}
    for number, role in enumerate(("build", "inspection")):
        parent = repository / "build/gate01" / builder
        base = parent / ("kernel-podman-build" if role == "build" else "kernel-podman-inspect")
        scratch = parent / ("kernel-build-scratch" if role == "build" else "kernel-inspection-scratch")
        if probe_root is not None and role == "build":
            base, scratch = probe_root / "store", probe_root / "scratch"
        runroot, graphroot = base / "runroot", base / "root"
        container_id = ("a" if role == "build" else "c") * 64
        runtime = runroot / "vfs-containers" / container_id / "userdata"
        static = graphroot / "vfs-containers" / container_id / "userdata"
        image_root = graphroot / "vfs/dir" / ("b" * 64)
        if normalization_audit is not None and role == "build":
            image_root = image_root.with_name(normalization_audit[0].after_anchor.basename)
        raw, spec = _mount_fixture()
        substitutions = {spec["root"]["path"]: str(image_root), "/private/scratch": str(scratch), "/store/runroot/vfs-containers/" + "a" * 64 + "/userdata/.containerenv": str(runtime / ".containerenv")}
        for old, new in substitutions.items():
            raw = raw.replace(old.encode(), new.encode())
        if normalization_audit is not None and role == "build":
            observed_dev = normalization_audit[0].raw_entries["/"].dev
            raw = raw.replace(b"259:6", f"{os.major(observed_dev)}:{os.minor(observed_dev)}".encode("ascii"))
        raw = raw.replace(("/app.slice/" + "a" * 64).encode(), ("/app.slice/" + container_id).encode())
        spec["root"]["path"] = str(image_root)
        for mount in spec["mounts"]:
            mount["source"] = substitutions.get(mount["source"], mount["source"])
        graph = _verify_live_mountinfo(raw, spec, ownership_projection=_fixture_projection())
        host = _live_fixture()
        host["mount_graph"] = graph
        dev = os.makedev(259, 6)
        if normalization_audit is not None and role == "build": dev = observed_dev
        for executable in (host["exe"], *host["mapped_files"].values()):
            executable["dev"] = dev
        sequence = 1000 + number * 100
        def binding(ino: int) -> dict[str, int]:
            return {"dev": dev, "gid": gid, "ino": ino, "mode": 0o700, "parent_dev": dev, "parent_ino": sequence, "uid": uid}
        scratch_binding = binding(sequence + 1)
        def runtime_stat(ino: int, kind: int, mode: int) -> dict[str, int]:
            return {"dev": dev, "gid": gid, "ino": ino, "mode": mode, "mtime_ns": 100, "ctime_ns": 100, "nlink": 1, "size": 0, "type": kind, "uid": uid}
        survivor = {name: runtime_stat(sequence + index + 10, stat.S_IFREG if name == "config.json" else stat.S_IFDIR, 0o644 if name == "config.json" else 0o700 if name == "shm" else 0o755) for index, name in enumerate(("artifacts", "config.json", "secrets", "shm"))}
        endpoint = {name: runtime_stat(sequence + index + 20, stat.S_IFSOCK if name == "attach" else stat.S_IFIFO, 0o700 if name == "attach" else 0o640) for index, name in enumerate(("attach", "ctl", "winsz"))}
        events = [{"cookie": 0, "mask": mask, "name": name, "watch": 1} for name, mask in (("attach", 512), ("ctl", 8), ("ctl", 512), ("winsz", 8), ("winsz", 512))]
        stop = {"allowed_removed_names": ["attach", "ctl", "winsz"], "endpoint_metadata": endpoint, "event_multiset": [{**event, "count": 1} for event in sorted(events, key=lambda row: (row["watch"], row["mask"], row["cookie"], row["name"]))], "observed_events": events, "pre_listing": ["artifacts", "attach", "config.json", "ctl", "secrets", "shm", "winsz"], "post_listing": list(survivor), "pre_parent_metadata": runtime_stat(sequence + 30, stat.S_IFDIR, 0o700), "post_parent_metadata": runtime_stat(sequence + 30, stat.S_IFDIR, 0o700), "state": "post-stop", "survivor_metadata": {name: {"before": dict(value), "after": dict(value)} for name, value in survivor.items()}}
        watcher, conmon_target = _a3_runtime_input_binding(
            dev=dev, uid=uid, gid=gid, sequence=sequence, config_stop=stop,
            initially_present=initially_present_by_role[role],
        )
        root_raw = {"dev": dev, "ino": sequence + 40, "nlink": 2, "mode": stat.S_IFDIR | 0o755, "uid": 0, "gid": 0, "rdev": 0, "size": 4096, "mtime_ns": 0, "ctime_ns": 100}
        if normalization_audit is not None and role == "build": root_raw = proof_io._json_safe(normalization_audit[0].after_anchor.root)
        expected = capsule["oci_rootfs"]
        authority = {key: copy.deepcopy(expected[key]) for key in ("archive_sha256", "config_digest", "diff_ids", "manifest_digest", "semantic_sha256")}
        projection = {"path": "/run/.containerenv", "kind": "file", "mode": 0o644, "uid": 0, "gid": 0, "mtime_ns": 100, "size": 20, "content_sha256": "e" * 64, "symlink_target": None, "xattrs": [], "hardlink_group": None}
