class RoundSixAuditTests(unittest.TestCase):
    def test_all_terminal_resource_owners_detach_before_first_or_middle_close_failure(self) -> None:
        from types import SimpleNamespace
        for kind in ("scoped", "watched", "live", "workspace"):
            for failing in (0, 1):
                with self.subTest(kind=kind, failing=failing), tempfile.TemporaryFile() as source:
                    fds = [os.dup(source.fileno()) for _ in range(4)]
                    if kind == "scoped":
                        owner = object.__new__(proof_io.BoundScopedDiff)
                        owner._closed, owner._nodes, owner._parent = False, {str(index): {"fd": fd} for index, fd in enumerate(fds[:3])}, fds[3]
                        detached = lambda: not owner._nodes and owner._parent == -1
                        current_detached = lambda fd: owner._parent != fd and all(node["fd"] != fd for node in owner._nodes.values())
                    elif kind == "watched":
                        owner = object.__new__(container_runtime.WatchedRuntimeBindings)
                        owner._closed, owner._records, owner._parents_by_watch, owner._watch_descriptor = False, {str(index): SimpleNamespace(descriptor=fd) for index, fd in enumerate(fds[:2])}, {1: SimpleNamespace(descriptor=fds[2])}, fds[3]
                        detached = lambda: not owner._records and not owner._parents_by_watch and owner._watch_descriptor == -1
                        current_detached = lambda fd: owner._watch_descriptor != fd and all(record.descriptor != fd for record in owner._records.values()) and all(record.descriptor != fd for record in owner._parents_by_watch.values())
                    elif kind == "live":
                        owner = object.__new__(container_runtime.BoundLiveProcess)
                        owner.closed = False
                        owner.root_fd, owner.proc_fd, owner.proc_parent_fd, owner.pidfd = fds
                        detached = lambda: (owner.root_fd, owner.proc_fd, owner.proc_parent_fd, owner.pidfd) == (-1, -1, -1, -1)
                        current_detached = lambda fd: detached()
                    else:
                        owner = object.__new__(kernel_build._BuilderWorkspace)
                        owner._closed, owner._lock_descriptor, owner._directory_descriptors = False, fds[0], tuple(fds[1:])
                        detached = lambda: owner._lock_descriptor == -1 and not owner._directory_descriptors
                        current_detached = lambda fd: detached()
                    original, attempts, states = os.close, [], []
                    def close(fd):
                        states.append(current_detached(fd))
                        original(fd)
                        attempts.append(fd)
                        if len(attempts) - 1 == failing: raise OSError(errno.EIO, "/sensitive/close")
                    with mock.patch.object(os, "close", side_effect=close):
                        with self.assertRaises(RuntimeError): owner.close()
                        owner.close()
                    self.assertCountEqual(attempts, fds)
                    self.assertTrue(all(states))
                    self.assertTrue(detached())

    def test_post_open_allocation_failures_release_public_outputs_and_temporary_names(self) -> None:
        for kind in ("copy", "publish", "log", "receipt", "json"):
            for close_failure in (False, True):
                with self.subTest(kind=kind, close_failure=close_failure), tempfile.TemporaryDirectory() as name, tempfile.TemporaryFile() as source:
                    source.write(b"public fixture")
                    source.flush()
                    output = Path(name) / "output"
                    primary = MemoryError("injected post-acquisition allocation")
                    original_open, original_close = os.open, os.close
                    owned = []
                    def opening(*args, **kwargs):
                        fd = original_open(*args, **kwargs)
                        owned.append(fd)
                        return fd
                    def close(fd):
                        original_close(fd)
                        if close_failure and fd in owned: raise OSError(errno.EIO, "/sensitive/close")
                    baseline = len(os.listdir("/proc/self/fd"))
                    try:
                        with contextlib.ExitStack() as patches:
                            patches.enter_context(mock.patch.object(os, "open", side_effect=opening))
                            patches.enter_context(mock.patch.object(os, "close", side_effect=close))
                            if kind in {"copy", "publish", "log"}: patches.enter_context(mock.patch.object(hashlib, "sha256", side_effect=primary))
                            else: patches.enter_context(mock.patch.object(proof_io if kind == "receipt" else rpm_artifacts, "Path", side_effect=primary))
                            with self.assertRaises(BaseException) as caught:
                                if kind == "copy": proof_io._copy_descriptor_to_path(source.fileno(), output, mode=0o644)
                                elif kind == "publish": proof_io._publish_descriptor(source.fileno(), output)
                                elif kind == "log": proof_io._publish_build_log(source.fileno(), output, {})
                                elif kind == "receipt": proof_io._publish_receipt(output, {"verdict": "pass"})
                                else: rpm_artifacts._atomic_write_json(output, {"verdict": "pass"})
                        self.assertIs(caught.exception, primary)
                        self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
                        self.assertEqual(os.listdir(name), [])
                        if close_failure: self.assertTrue(primary.__notes__)
                    finally:
                        for fd in owned:
                            try: original_close(fd)
                            except OSError as error:
                                if error.errno != errno.EBADF: raise

