                baseline = len(os.listdir("/proc/self/fd"))
                with mock.patch.object(kernel_build._BuilderWorkspace, "open", return_value=workspace), mock.patch.object(fcntl, "flock", side_effect=flock), mock.patch.object(os, "close", side_effect=close):
                    with self.assertRaises(BaseException) as caught:
                        with kernel_build._proof_locks(Path(name), builders=("builder-a",), output_role="fixture"):
                            if has_primary: raise primary
                self.assertEqual(events, ["workspace", "unlock", "close"])
                if has_primary:
                    self.assertIs(caught.exception, primary)
                    self.assertEqual(primary.__notes__, ["additional proof workspace cleanup failed", "additional proof output unlock failed", "additional proof output close failed"])
                self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)

