class RoundSixPrimaryTests(unittest.TestCase):
    def test_real_store_policy_exit_cannot_hide_create_or_start_ownership(self) -> None:
        for phase in ("create", "start"):
            with self.subTest(phase=phase), tempfile.TemporaryDirectory() as name:
                primary = ValueError("injected post-command policy release")
                calls, material, observed = [], [], []
                faulted = False
                class Policy:
                    @contextlib.contextmanager
                    def child_configuration(self, environment, descriptors):
                        nonlocal faulted
                        yield environment, descriptors
                        if calls[-1] == phase and not faulted:
                            faulted = True
                            observed.append((backend._created, backend._started))
                            raise primary
                store = PodmanStore(Path(name) / "inert-store", environment={}, policy=Policy())
                store.verify_scope = mock.Mock()
                store.verify_cleanup_scope = mock.Mock()
                backend = container_runtime.PodmanContainerBackend(store=store, image="sha256:" + "a" * 64, container="fixture", scratch=Path(name), capsule_descriptor=20, archive_descriptor=18, archive_sha256="a" * 64, manifest_digest="sha256:" + "b" * 64, execution_arguments={})
                def command(arguments, **kwargs):
                    verb = arguments[9]
                    calls.append(verb)
                    if verb == "create": material.append("container")
                    if verb == "rm": material.clear()
                    return subprocess.CompletedProcess(arguments, 0, b"fixture\n" if verb == "create" else b"0\n", b"")
                if phase == "start":
                    material.append("container")
                    backend._created = True
                    backend._state = container_runtime.LifecycleState.CREATED_INIT_AUDITED
                    backend._config_inputs = mock.Mock()
                    backend._conmon_binding = mock.Mock(target_descriptor=None)
                try:
                    with mock.patch.object(container_runtime.subprocess, "run", side_effect=command):
                        with self.assertRaises(BaseException) as caught:
                            try:
                                if phase == "create": backend.create()
                                else: backend.start()
                            except BaseException:
                                try: backend.remove()
                                except BaseException: proof_io._add_cleanup_note(primary, "additional fixture removal failed")
                                raise
                    self.assertIs(caught.exception, primary)
                    self.assertEqual(observed, [(True, phase == "start")])
                    self.assertIn("rm", calls)
                    if phase == "start": self.assertIn("stop", calls)
                    self.assertFalse(material)
                    self.assertFalse(backend._created or backend._started or backend._conmon_present)
                finally: backend.close()

    def test_partial_conmon_bind_keeps_real_descriptor_until_forced_removal(self) -> None:
        with tempfile.TemporaryDirectory() as name:
            root = Path(name); baseline = set(os.listdir("/proc/self/fd"))
            backend, store, policy, events, command = BoundInputTests()._a2r2_real_backend(
                root, initially_present=False
            )
            binding = backend._conmon_binding
            watcher = backend._config_inputs
            primary = ValueError("injected held conmon validation")
            cleanup = OSError(errno.EIO, "injected terminal watcher cleanup")
            real_binding_verify = binding.verify
            real_coherent = watcher.verify_coherent
            binding_verify_calls = coherent_calls = 0
            binding_injected = watcher_injected = False
            def verify_binding(*, require_present=True):
                nonlocal binding_verify_calls, binding_injected
                binding_verify_calls += 1
                if binding.target_descriptor is not None and binding_verify_calls == 3:
                    binding_injected = True
                    raise primary
                return real_binding_verify(require_present=require_present)
            def coherent():
                nonlocal coherent_calls, watcher_injected
                coherent_calls += 1
                value = real_coherent()
                reserved = watcher._reserved_lifecycle
                if (
                    not watcher_injected
                    and reserved is not None
                    and reserved["stop_state"] == "complete"
                ):
                    watcher_injected = True
                    raise cleanup
                return value
            try:
                with (
                    mock.patch.object(store, "run", side_effect=command),
                    mock.patch.object(binding, "verify", side_effect=verify_binding),
                    mock.patch.object(watcher, "verify_coherent", side_effect=coherent),
                ):
                    with self.assertRaises(ValueError) as caught:
                        try: backend.start()
                        except BaseException as error:
                            self.assertIsNotNone(binding.target_descriptor)
                            self.assertTrue(stat.S_ISREG(os.fstat(binding.target_descriptor).st_mode))
                            self.assertTrue(backend._started and backend._conmon_present)
                            proof_io._release_preserving_primary((backend.remove,), error)
                            raise
                self.assertIs(caught.exception, primary)
                self.assertEqual(
                    events,
                    [
                        ("start", "fixture"),
                        ("stop", "--time", "30", "fixture"),
                        ("wait", "fixture"),
                        ("stop", "--time", "30", "fixture"),
                        ("rm", "--force", "fixture"),
                    ],
                )
                self.assertTrue(binding_injected)
                self.assertTrue(watcher_injected)
                self.assertGreaterEqual(coherent_calls, 4)
                self.assertTrue(primary.__notes__)
                self.assertFalse(backend._created or backend._started or backend._conmon_present)
                self.assertFalse(command.pid.exists())
                self.assertFalse(command.config_material.exists())
                self.assertFalse(command.runtime_material.exists())
            finally:
                inputs = backend._config_inputs
                if inputs is not None:
                    inputs.close(); backend._config_inputs = None
                command.close(); command.close()
                backend.close(); backend.close(); store.close_scope(); policy.close()
            self.assertEqual(set(os.listdir("/proc/self/fd")), baseline)

