    def test_partial_start_and_stop_always_reach_exact_created_container_removal(self) -> None:
        for phase in ("start-bind", "wait-error", "wait-malformed", "stop-side-effect"):
            with self.subTest(phase=phase), tempfile.TemporaryDirectory() as name:
                root = Path(name); baseline = set(os.listdir("/proc/self/fd"))
                backend, store, policy, commands, command = BoundInputTests()._a2r2_real_backend(
                    root, initially_present=False
                )
                binding = backend._conmon_binding
                primary = ValueError("injected lifecycle boundary")
                real_bind = binding.bind_present_target
                def bind():
                    real_bind()
                    raise primary
                def running(arguments, **kwargs):
                    result = command(arguments, **kwargs)
                    if arguments[0] == "stop" and phase == "stop-side-effect":
                        raise primary
                    if arguments[0] == "wait":
                        if phase == "wait-error": raise primary
                        if phase == "wait-malformed":
                            return subprocess.CompletedProcess(arguments, 0, b"invalid\n", b"")
                    return result
                try:
                    bind_context = (
                        mock.patch.object(binding, "bind_present_target", side_effect=bind)
                        if phase == "start-bind" else contextlib.nullcontext()
                    )
                    with mock.patch.object(store, "run", side_effect=running), bind_context:
                        with self.assertRaises(BaseException) as caught:
                            try:
                                backend.start()
                                backend.stop_and_wait()
                            except BaseException as error:
                                proof_io._release_preserving_primary((backend.remove,), error)
                                raise
                    if phase != "wait-malformed": self.assertIs(caught.exception, primary)
                    verbs = [arguments[0] for arguments in commands]
                    self.assertIn("stop", verbs)
                    self.assertIn("rm", verbs)
                    self.assertFalse(command.config_material.exists())
                    self.assertFalse(command.runtime_material.exists())
                    self.assertFalse(backend._created or backend._started or backend._conmon_present)
                finally:
                    inputs = backend._config_inputs
                    if inputs is not None:
                        inputs.close(); backend._config_inputs = None
                    command.close(); command.close()
                    backend.close(); backend.close(); store.close_scope(); policy.close()
                self.assertEqual(set(os.listdir("/proc/self/fd")), baseline)

