    def test_tree_and_file_rollback_preserve_primary_and_every_cleanup_category(self) -> None:
        for kind in ("tree", "file", "corrupt-file"):
            for failure in ("first", "middle", "close"):
                with self.subTest(kind=kind, failure=failure), tempfile.TemporaryDirectory() as name:
                    root = Path(name)
                    final, receipt = root / "kernel", root / "kernel.receipt.json"
                    primary = RuntimeError("injected publication boundary")
                    calls, close_calls = [], []
                    original_unlink, original_close, original_write = os.unlink, os.close, os.write
                    callbacks = 0
                    def boundary():
                        nonlocal callbacks
                        callbacks += 1
                        if kind == "tree" or callbacks == 2: raise primary
                    def unlink(path, **kwargs):
                        calls.append(Path(path).name)
                        if failure == "first" and len(calls) == 1:
                            raise OSError(errno.EIO, "/sensitive/rollback")
                        return original_unlink(path, **kwargs)
                    renames = 0
                    def rename(source, destination):
                        nonlocal renames
                        renames += 1
                        if renames == 2:
                            calls.append("rename-back")
                            if failure == "middle": raise OSError(errno.EIO, "/sensitive/rename")
                        return proof_io._rename_noreplace(source, destination)
                    def close(fd):
                        original_close(fd)
                        if calls:
                            close_calls.append(fd)
                            if failure == "close": raise OSError(errno.EIO, "/sensitive/close")
                    def write(fd, value):
                        return original_write(fd, bytes(value).replace(b"pass", b"fail"))
                    if kind == "tree":
                        candidate, allowed = ReceiptProtocolTests()._candidate(root)
                        value = create_detached_receipt(candidate, intended_path=final, allowed_files=allowed, source_capsule_sha256="a" * 64, rpm_manifest_sha256="b" * 64, expected_uid=os.geteuid(), expected_gid=os.getegid())
                    baseline = len(os.listdir("/proc/self/fd"))
                    try:
                        with contextlib.ExitStack() as patches:
                            patches.enter_context(mock.patch.object(os, "unlink", side_effect=unlink))
                            patches.enter_context(mock.patch.object(os, "close", side_effect=close))
                            if kind == "corrupt-file": patches.enter_context(mock.patch.object(os, "write", side_effect=write))
                            if kind == "file" and failure == "middle":
                                def second_unlink(path, **kwargs):
                                    calls.append(Path(path).name)
                                    if len(calls) == 2: raise OSError(errno.EIO, "/sensitive/payload")
                                    return original_unlink(path, **kwargs)
                                patches.enter_context(mock.patch.object(os, "unlink", side_effect=second_unlink))
                            with self.assertRaises(BaseException) as caught:
                                if kind == "tree":
                                    publish_candidate(candidate, final, receipt, value, rename_noreplace=rename, before_receipt=boundary, expected_uid=os.geteuid(), expected_gid=os.getegid())
                                else:
                                    proof_io.publish_evidence_file(b'{"verdict":"pass"}', final=final, receipt=receipt, kind="comparison", input_sha256={"fixture": "a" * 64}, before_receipt=boundary, expected_uid=os.geteuid(), expected_gid=os.getegid())
                        if kind != "corrupt-file": self.assertIs(caught.exception, primary)
                        if kind == "tree": self.assertEqual(calls, [receipt.name, "rename-back"])
                        elif kind == "file": self.assertEqual(calls, [receipt.name, final.name])
                        else: self.assertFalse(receipt.exists())
                        if not (kind == "corrupt-file" and failure == "middle"):
                            self.assertTrue(getattr(caught.exception, "__notes__", []))
                            self.assertNotIn("sensitive", str(caught.exception.__notes__))
                        self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
                    finally:
                        for path in (receipt, final):
                            if path.is_file(): path.unlink()

    def test_receipt_stack_callbacks_preserve_primary_before_durability(self) -> None:
        for primary_present in (False, True):
            boundary = kernel_build._ReceiptBoundary(lambda: None)
            primary = ValueError("injected callback body")
            attempts = []
            def release(category):
                attempts.append(category)
                if category != "last": raise OSError(errno.EIO, "/sensitive/callback")
            with self.subTest(primary=primary_present), self.assertRaises(BaseException) as caught:
                with kernel_build._ReceiptExitStack(boundary) as stack:
                    for category in ("last", "middle", "first"):
                        stack.callback(release, category)
                    if primary_present: raise primary
            self.assertEqual(attempts, ["first", "middle", "last"])
            if primary_present:
                self.assertIs(caught.exception, primary)
                self.assertEqual(len(primary.__notes__), 2)
                self.assertNotIn("sensitive", str(primary.__notes__))

    def test_builder_setup_and_final_cleanup_keep_primary_with_each_diagnostic(self) -> None:
        for phase in ("setup", "resources"):
            with self.subTest(phase=phase), tempfile.TemporaryDirectory() as name:
                root = Path(name)
                with mock.patch.object(kernel_build, "_validated_repository", return_value=root):
                    workspace = kernel_build._BuilderWorkspace.open(root, "builder-a")
                primary = ValueError("injected builder primary")
                attempts = []
                original_close = workspace.close
                def close():
                    attempts.append("workspace")
                    original_close()
                    raise OSError(errno.EIO, "/sensitive/workspace")
                baseline = len(os.listdir("/proc/self/fd")) - len(workspace._directory_descriptors) - 1
                policy = None
                original_policy = container_runtime.SealedPodmanPolicy.create
                def policy_factory():
                    nonlocal policy
                    policy = original_policy()
                    release = policy.close
                    def policy_close():
                        attempts.append("policy")
                        release()
                        raise OSError(errno.EIO, "/sensitive/policy")
                    policy.close = policy_close
                    return policy
                with contextlib.ExitStack() as patches:
                    patches.enter_context(mock.patch.object(kernel_build, "_validate_outer_environment", return_value={}))
                    patches.enter_context(mock.patch.object(kernel_build, "_validated_repository", return_value=root))
                    workspace_open = patches.enter_context(mock.patch.object(kernel_build._BuilderWorkspace, "open", return_value=workspace))
                    patches.enter_context(mock.patch.object(workspace, "close", side_effect=close))
                    if phase == "setup": patches.enter_context(mock.patch.object(kernel_build, "_require_direct_child", side_effect=primary))
                    else:
                        patches.enter_context(mock.patch.object(kernel_build.SealedPodmanPolicy, "create", side_effect=policy_factory))
                        patches.enter_context(mock.patch.object(kernel_build, "gate01_input_paths", side_effect=primary))
                    with self.assertRaises(BaseException) as caught:
                        kernel_build.run_builder.__wrapped__(root, "builder-a", _code_authority=None)
                self.assertIs(caught.exception, primary)
                if phase == "setup":
                    workspace_open.assert_not_called()
                    original_close()
                self.assertEqual(attempts, [] if phase == "setup" else ["policy", "workspace"])
                self.assertEqual(len(getattr(primary, "__notes__", [])), len(attempts))
                self.assertNotIn("sensitive", str(getattr(primary, "__notes__", [])))
                self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)

