class RoundSixCleanupTests(unittest.TestCase):
    def test_store_creation_watch_parser_rejects_unbounded_or_malformed_records(self) -> None:
        def event(mask=container_runtime._IN_CREATE | container_runtime._IN_ISDIR, name=b"store", cookie=0):
            payload = name + b"\0"
            payload += bytes((-len(payload)) % 16)
            return struct.pack("=iIII", 7, mask, cookie, len(payload)) + payload
        valid = event()
        with mock.patch.object(os, "read", side_effect=[valid, BlockingIOError()]):
            self.assertEqual(container_runtime._read_creation_events(90), ((7, container_runtime._IN_CREATE | container_runtime._IN_ISDIR, 0, b"store"),))
        for raw in (b"", valid[:8], valid[:-1], valid * 3, event(name=b"a/b"), valid[:16] + b"store\0x" + valid[23:], struct.pack("=iIII", 7, 1, 0, 272) + bytes(272)):
            with self.subTest(raw_length=len(raw)), mock.patch.object(os, "read", side_effect=[raw, BlockingIOError()]):
                with self.assertRaises(RuntimeError): container_runtime._read_creation_events(90)

    def test_store_creation_custody_and_event_fault_matrix(self) -> None:
        for child in ("store", "root", "runroot", "tmp"):
            for phase in ("fstat", "registration", "overflow", "extra", "read", "watch"):
                with self.subTest(child=child, phase=phase), tempfile.TemporaryDirectory() as name, contextlib.closing(container_runtime.SealedPodmanPolicy.create()) as policy:
                    store = PodmanStore(Path(name) / "store", environment={}, policy=policy)
                    original_mkdir, original_fstat, original_events, original_watch = os.mkdir, os.fstat, container_runtime._read_creation_events, container_runtime._add_inotify_directory_watch
                    primary = MemoryError("injected created-directory custody")
                    created = fired = False
                    def mkdir(path, *args, **kwargs):
                        nonlocal created
                        result = original_mkdir(path, *args, **kwargs)
                        if path == child: created = True
                        return result
                    def fstat(fd):
                        nonlocal fired
                        if created and not fired and phase == "fstat":
                            fired = True
                            raise primary
                        return original_fstat(fd)
                    class Bindings(dict):
                        def __setitem__(self, key, value):
                            nonlocal fired
                            if value.path.name == child and phase == "registration":
                                fired = True
                                raise primary
                            super().__setitem__(key, value)
                    store._directory_bindings = Bindings()
                    def events(fd):
                        nonlocal fired
                        if created and not fired and phase in {"overflow", "extra", "read"}:
                            fired = True
                            if phase == "read": raise primary
                            result = original_events(fd)
                            return ((-1, 0x4000, 0, b""),) if phase == "overflow" else (*result, (result[0][0], container_runtime._IN_ATTRIB, 0, b"unrelated"))
                        return original_events(fd)
                    watched = 0
                    def watch(*args):
                        nonlocal watched, fired
                        watched += 1
                        if phase == "watch" and watched == ("store", "root", "runroot", "tmp").index(child) + 1:
                            fired = True
                            raise primary
                        return original_watch(*args)
                    baseline = len(os.listdir("/proc/self/fd"))
                    with mock.patch.object(os, "mkdir", side_effect=mkdir), mock.patch.object(os, "fstat", side_effect=fstat), mock.patch.object(container_runtime, "_read_creation_events", side_effect=events), mock.patch.object(container_runtime, "_add_inotify_directory_watch", side_effect=watch):
                        with self.assertRaises(BaseException) as caught: store.initialize()
                    self.assertTrue(fired)
                    if phase in {"fstat", "registration", "read", "watch"}: self.assertIs(caught.exception, primary)
                    if phase in {"overflow", "extra"}:
                        self.assertTrue(getattr(caught.exception, "__notes__", []))
                        self.assertTrue((Path(name) / "store" if child == "store" else store.base / child).is_dir())
                        store.close_scope()
                    else:
                        with mock.patch.object(store, "run", return_value=subprocess.CompletedProcess([], 1)):
                            try: container_runtime._remove_podman_store(store)
                            except RuntimeError: pass
                        self.assertFalse(store.base.exists())
                    self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)

    def test_store_created_directory_has_custody_before_first_observation(self) -> None:
        for child in ("store", "root", "runroot", "tmp"):
            for phase in ("stat", "open"):
                with self.subTest(child=child, phase=phase), tempfile.TemporaryDirectory() as name, contextlib.closing(container_runtime.SealedPodmanPolicy.create()) as policy:
                    store = container_runtime.PodmanStore(Path(name) / "store", environment={}, policy=policy)
                    original_mkdir, original_stat, original_open = os.mkdir, os.stat, os.open
                    primary = MemoryError("injected first created-directory observation")
                    created, injected = False, False
                    def mkdir(path, *args, **kwargs):
                        nonlocal created
                        result = original_mkdir(path, *args, **kwargs)
                        if path == child: created = True
                        return result
                    def fault(original, path, *args, **kwargs):
                        nonlocal injected
                        if created and not injected and path == child:
                            injected = True
                            raise primary
                        return original(path, *args, **kwargs)
                    baseline = len(os.listdir("/proc/self/fd"))
                    with mock.patch.object(os, "mkdir", side_effect=mkdir), mock.patch.object(os, phase, side_effect=lambda *args, **kwargs: fault(original_stat if phase == "stat" else original_open, *args, **kwargs)):
                        with self.assertRaises(BaseException) as caught: store.initialize()
                    self.assertIs(caught.exception, primary)
                    self.assertTrue(injected)
                    with mock.patch.object(store, "run", return_value=subprocess.CompletedProcess([], 1)):
                        try: container_runtime._remove_podman_store(store)
                        except RuntimeError: pass
                    self.assertFalse(store.base.exists())
                    self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)

    def test_store_first_open_failure_cannot_adopt_a_replacement(self) -> None:
        with tempfile.TemporaryDirectory() as name, contextlib.closing(container_runtime.SealedPodmanPolicy.create()) as policy:
            root = Path(name)
            store = container_runtime.PodmanStore(root / "store", environment={}, policy=policy)
            original_open = os.open
            primary = MemoryError("injected replaced initial directory")
            injected = False
            def opening(path, *args, **kwargs):
                nonlocal injected
                if path == "store" and not injected:
                    injected = True
                    store.base.rename(root / "original")
                    store.base.mkdir(mode=0o700)
                    (store.base / "foreign").write_bytes(b"must survive")
                    raise primary
                return original_open(path, *args, **kwargs)
            baseline = len(os.listdir("/proc/self/fd"))
            with mock.patch.object(os, "open", side_effect=opening):
                with self.assertRaises(BaseException) as caught: store.initialize()
            self.assertIs(caught.exception, primary)
            store.close_scope()
            self.assertEqual((store.base / "foreign").read_bytes(), b"must survive")
            self.assertTrue((root / "original").is_dir())
            self.assertTrue(primary.__notes__)
            self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)

    def test_store_partial_initialization_keeps_created_directory_custody(self) -> None:
        for fail_at in range(1, 5):
            with self.subTest(fail_at=fail_at), tempfile.TemporaryDirectory() as name, contextlib.closing(container_runtime.SealedPodmanPolicy.create()) as policy:
                store = container_runtime.PodmanStore(Path(name) / "store", environment={}, policy=policy)
                original, calls = container_runtime.BoundScratch.open, []
                primary = MemoryError("injected initial binding")
                def opening(*args, **kwargs):
                    calls.append(args[0])
                    if len(calls) == fail_at: raise primary
                    return original(*args, **kwargs)
                baseline = len(os.listdir("/proc/self/fd"))
                with mock.patch.object(container_runtime.BoundScratch, "open", side_effect=opening):
                    with self.assertRaises(BaseException) as caught: store.initialize()
                self.assertIs(caught.exception, primary)
                with mock.patch.object(store, "run", return_value=subprocess.CompletedProcess([], 1)):
                    with self.assertRaises(RuntimeError): container_runtime._remove_podman_store(store)
                self.assertFalse(store.base.exists())
                self.assertTrue(store._scope_closed)
                self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)

    def test_failed_base_binding_never_reacquires_replacement_store(self) -> None:
        with tempfile.TemporaryDirectory() as name, contextlib.closing(container_runtime.SealedPodmanPolicy.create()) as policy:
            root = Path(name)
            store = container_runtime.PodmanStore(root / "store", environment={}, policy=policy)
            primary = ValueError("injected failed initial store binding")
            def opening(*args, **kwargs):
                store.base.rename(root / "original-store")
                store.base.mkdir(mode=0o700)
                (store.base / "root").mkdir(mode=0o700)
                (store.base / "root/foreign").write_bytes(b"must survive")
                raise primary
            baseline = len(os.listdir("/proc/self/fd"))
            with mock.patch.object(container_runtime.BoundScratch, "open", side_effect=opening):
                with self.assertRaises(BaseException) as caught: store.initialize()
            self.assertIs(caught.exception, primary)
            def command(*args, **kwargs):
                import shutil
                for child in store.base.iterdir(): shutil.rmtree(child)
                return subprocess.CompletedProcess([], 0)
            with mock.patch.object(store, "run", side_effect=command):
                with self.assertRaises(RuntimeError): container_runtime._remove_podman_store(store)
            self.assertEqual((store.base / "root/foreign").read_bytes(), b"must survive")
            self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)

