    def test_failed_store_command_still_attempts_exact_children_and_final_rmdir(self) -> None:
        import shutil
        for failing_child in (None, "root", "runroot"):
            with self.subTest(failing_child=failing_child), tempfile.TemporaryDirectory() as name, contextlib.closing(container_runtime.SealedPodmanPolicy.create()) as policy:
                store = container_runtime.PodmanStore(Path(name) / "store", environment={}, policy=policy)
                store.initialize()
                baseline = len(os.listdir("/proc/self/fd")) - 8
                original = shutil.rmtree
                attempts = []
                def removing(path, **kwargs):
                    attempts.append(path)
                    if path == failing_child: raise OSError(errno.EIO, "/sensitive/child")
                    return original(path, **kwargs)
                with mock.patch.object(store, "run", return_value=subprocess.CompletedProcess([], 1, b"", b"")), mock.patch.object(shutil, "rmtree", side_effect=removing):
                    with self.assertRaisesRegex(RuntimeError, "user-namespace cleanup failed"):
                        container_runtime._remove_podman_store(store)
                self.assertEqual(attempts, ["root", "runroot", "tmp"])
