    def test_lazy_production_factories_have_exact_concrete_drain_pairings(self) -> None:
        import ast
        expected = {"BoundInputs.open": "_drain_bound_inputs", "BoundScopedDiff.open": "_drain_bound_scoped_diff", "BoundAcceptedTree.open": "_drain_bound_accepted_tree", "BoundEvidenceReceipt.open": "_drain_bound_evidence_receipt", "_RepairParentWatch.open": "_drain_repair_parent_watch", "SealedPodmanPolicy.create": "_drain_podman_policy", "_executed_capsule_from_bound_inputs": "_drain_sealed_capsule"}
        observed = {}
        count = 0
        for module in (proof_io, kernel_build, __import__("tools.gate01.oci_rootfs", fromlist=["oci_rootfs"])):
            for node in ast.walk(ast.parse(inspect.getsource(module))):
                if not isinstance(node, ast.Call): continue
                if not (isinstance(node.func, ast.Name) and node.func.id == "_owned_resource" or isinstance(node.func, ast.Attribute) and node.func.attr == "open_owned"): continue
                self.assertGreaterEqual(len(node.args), 2)
                factory, drain = ast.unparse(node.args[0]), ast.unparse(node.args[1])
                self.assertEqual(drain, expected[factory])
                self.assertTrue(callable(getattr(module, drain)))
                observed[factory] = drain
                count += 1
        self.assertEqual(observed, expected)
        self.assertEqual(count, 16)

