    def test_scoped_material_cleanup_iterator_and_listing_faults_keep_last_attempt(self) -> None:
        import dis
        import inspect
        for phase in ("names", "targets", "orphan", "setup"):
            with self.subTest(phase=phase), tempfile.TemporaryDirectory() as name:
                parent = Path(name)
                baseline = len(os.listdir("/proc/self/fd"))
                primary = ValueError("injected scoped setup primary")
                if phase == "setup":
                    function = kernel_build._create_scoped_temporary_tree
                    needle = "for entry in os.listdir(parent_descriptor):"
                    def fail(path, mode):
                        path.with_name(path.name + ".escaped-original").mkdir(
                            mode=0o700
                        )
                        raise primary
                    call = lambda: function(parent, prefix=".fixture-", set_mode=fail)
                    tree = None
                else:
                    path = parent / "owned"
                    path.mkdir(mode=0o700)
                    other = parent / "other"
                    other.mkdir(mode=0o700)
                    (path / "child").write_bytes(b"owned")
                    tree = kernel_build._ScopedTemporaryTree.open(path)
                    if phase == "orphan": path.rename(other / "moved")
                    function, call = type(tree).remove, tree.remove
                    needle = {"names": "for name in names:", "targets": "for name in targets:", "orphan": "for name in tuple(os.listdir(self._root_descriptor)):"}[phase]
                try:
                    if needle in inspect.getsource(function):
                        with self._registration_fault(function, needle, "GET_ITER"):
                            with self.assertRaises(BaseException): call()
                    else:
                        # Only setup's non-cleanup random-name loop remains;
                        # all owned removal control must be scalar.
                        if phase != "setup": self.assertNotIn("GET_ITER", {op.opname for op in dis.get_instructions(function)})
                        if phase in ("setup", "orphan"):
                            with self.assertRaises(BaseException) as caught: call()
                            if phase == "setup": self.assertIs(caught.exception, primary)
                        else: call()
                    if phase == "orphan": self.assertEqual(list((other / "moved").iterdir()), [])
                    elif phase == "setup": self.assertEqual(list(parent.iterdir()), [])
                    else: self.assertFalse(path.exists())
                    self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
                finally:
                    if tree is not None: tree.close()

