    def test_absent_unbound_store_name_never_enters_combined_removal_authority(self) -> None:
        import shutil
        with tempfile.TemporaryDirectory() as name:
            store = PodmanStore(Path(name) / "store", environment={}, policy=mock.Mock())
            store.initialize()
            store.graphroot.rmdir()
            store._directory_bindings.pop("store-graphroot").close()
            original_stat = os.stat
            introduced = False
            def observe(path, *args, **kwargs):
                nonlocal introduced
                try: return original_stat(path, *args, **kwargs)
                except FileNotFoundError:
                    if path == "root" and kwargs.get("dir_fd") == store._directory_bindings["store-base"].descriptor and not introduced:
                        introduced = True
                        store.graphroot.mkdir(mode=0o700)
                        (store.graphroot / "foreign").write_bytes(b"must survive")
                    raise
            def command(*args, **kwargs):
                for child in (store.graphroot, store.runroot, store.tmpdir):
                    if child.exists(): shutil.rmtree(child)
                return subprocess.CompletedProcess([], 0, b"", b"")
            try:
                with mock.patch.object(os, "stat", side_effect=observe), mock.patch.object(store, "run", side_effect=command) as run:
                    with self.assertRaises(RuntimeError): _remove_podman_store(store)
                run.assert_not_called()
                self.assertTrue(introduced)
                self.assertEqual((store.graphroot / "foreign").read_bytes(), b"must survive")
                self.assertFalse(store.runroot.exists() or store.tmpdir.exists())
            finally: store.close_scope()

