            baseline = len(os.listdir("/proc/self/fd"))
            try:
                with mock.patch.object(container_runtime.BoundScratch, "open", side_effect=opening), mock.patch.object(store, "run") as command:
                    with self.assertRaises(BaseException) as caught: _remove_podman_store(store)
                self.assertIs(caught.exception, primary)
                self.assertEqual(primary.__notes__, ["additional Podman store base verification failed"])
                command.assert_not_called()
                for path in (store.graphroot, store.runroot, store.tmpdir): self.assertTrue(path.exists())
                self.assertTrue(store._scope_closed)
                self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
            finally: store.close_scope()

