    def test_inotify_acquisition_has_no_fallible_redundant_conversion(self) -> None:
        from tools.gate01 import oci_rootfs
        for function in (container_runtime._open_inotify, oci_rootfs._open_repair_watch, container_runtime._open_rootfs_file):
            with self.subTest(function=function.__name__):
                baseline = len(os.listdir("/proc/self/fd"))
                acquired = []
                original_cdll = container_runtime.ctypes.CDLL
                class Library:
                    def inotify_init1(self, flags):
                        fd = original_cdll(None, use_errno=True).inotify_init1(flags)
                        if fd >= 0: acquired.append(fd)
                        return fd
                    def syscall(self, *args):
                        fd = os.open("/dev/null", os.O_RDONLY)
                        acquired.append(fd)
                        return fd
                try:
                    arguments = (-1, "/inert") if function is container_runtime._open_rootfs_file else ()
                    with mock.patch.object(container_runtime.ctypes, "CDLL", return_value=Library()):
                        if "return int(descriptor)" in inspect.getsource(function):
                            with self._registration_fault(function, "return int(descriptor)", "CALL") as primary:
                                with self.assertRaises(BaseException) as caught: function(*arguments)
                            self.assertIs(caught.exception, primary)
                        else:
                            descriptor = function(*arguments)
                            self.assertIs(type(descriptor), int)
                            os.close(descriptor)
                    self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
                finally:
                    for value in acquired:
                        try: os.close(value)
                        except OSError: pass

    def test_cleanup_exception_snapshot_never_allocates_an_exc_info_tuple(self) -> None:
        import ast
        for module in (proof_io, container_runtime, kernel_build, rpm_artifacts):
            self.assertFalse("sys.exc_info()[1]" in inspect.getsource(module), module.__name__)
        for name in ("kernel_bootstrap", "oci_rootfs", "module_key"):
            self.assertFalse("sys.exc_info()[1]" in (REPO / "tools/gate01" / f"{name}.py").read_text(), name)
        for path in (REPO / "tools/gate01").glob("*.py"):
            if path.name == "inputs.py": continue
            for node in ast.walk(ast.parse(path.read_text())):
                if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
                    self.assertNotEqual(ast.unparse(node.func), "sys.exc_info", (path.name, node.lineno))

    def test_store_cleanup_uses_only_proven_subprocess_success_for_recreated_children(self) -> None:
        import shutil
        for outcome in ("success", "nonzero", "unproven"):
            with self.subTest(outcome=outcome), tempfile.TemporaryDirectory() as name:
                primary = ValueError("injected policy finalizer after store command")
                class Policy:
                    @contextlib.contextmanager
                    def child_configuration(self, environment, descriptors):
                        yield environment, descriptors
                        raise primary
                store = PodmanStore(Path(name) / "store", environment={}, policy=Policy())
                baseline = len(os.listdir("/proc/self/fd"))
                store.initialize()
                def command(*args, **kwargs):
                    for child in (store.graphroot, store.runroot, store.tmpdir):
                        shutil.rmtree(child)
                        child.mkdir(mode=0o700)
                        (child / "bookkeeping").write_bytes(b"public")
                    if outcome == "unproven": raise primary
                    return subprocess.CompletedProcess([], 0 if outcome == "success" else 1, b"", b"")
                try:
                    target, attribute = (store, "run") if outcome == "unproven" else (container_runtime.subprocess, "run")
                    with mock.patch.object(target, attribute, side_effect=command):
                        with self.assertRaises(BaseException) as caught: _remove_podman_store(store)
                    self.assertIs(caught.exception, primary)
                    self.assertEqual(store.base.exists(), outcome != "success")
                    if outcome != "success":
                        self.assertTrue(primary.__notes__)
                        for child in (store.graphroot, store.runroot, store.tmpdir): self.assertEqual((child / "bookkeeping").read_bytes(), b"public")
                    self.assertTrue(store._scope_closed)
                    self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
                finally: store.close_scope()

