    def test_lazy_owner_factory_yield_and_cleanup_have_no_snapshot_gap(self) -> None:
        for phase in ("factory", "yield", "snapshot", "body-close", "normal-close"):
            with self.subTest(phase=phase):
                resources = []
                baseline = len(os.listdir("/proc/self/fd"))
                primary = ValueError("injected lazy owner body")
                cleanup = OSError(errno.EIO, "injected lazy owner close")
                def factory():
                    resource = proof_io._DescriptorResource(os.open("/dev/null", os.O_RDONLY))
                    resources.append(resource)
                    if phase.endswith("close"):
                        original = resource.close
                        def close():
                            original()
                            raise cleanup
                        resource.close = close
                    return resource
                function = proof_io._owned_resource.__wrapped__
                fault = contextlib.nullcontext(primary)
                if phase == "factory": fault = self._registration_fault(function, "resource = factory(", "CALL_FUNCTION_EX")
                elif phase == "yield": fault = self._registration_fault(function, "yield resource", "YIELD_VALUE")
                elif phase == "snapshot" and "primary = sys.exc_info()[1]" in inspect.getsource(function): fault = self._registration_fault(function, "primary = sys.exc_info()[1]", "CALL")
                try:
                    with fault as injected:
                        with self.assertRaises(BaseException) as caught:
                            with proof_io._owned_resource(factory, proof_io._drain_descriptor_resource):
                                if phase in ("snapshot", "body-close"): raise primary
                    self.assertIs(caught.exception, cleanup if phase == "normal-close" else primary if phase in ("body-close", "snapshot") else injected)
                    if phase == "body-close": self.assertTrue(primary.__notes__)
                    self.assertTrue(all(resource.fd == -1 for resource in resources))
                    self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
                finally:
                    for resource in resources:
                        try: resource.close()
                        except OSError: pass

    def test_normalization_watch_callers_acquire_only_inside_context_entry(self) -> None:
        from dataclasses import replace
        from tools.gate01 import oci_rootfs
        for phase in ("runtime", "directory"):
            with self.subTest(phase=phase), tempfile.TemporaryDirectory() as name:
                # The external root anchor is part of the real authority.
                # Give it a private parent, not the concurrently used /tmp.
                root = Path(name) / "root"
                root.mkdir()
                (root / "target").write_bytes(b"public")
                observed = oci_rootfs.audit_rootfs(root)
                entries = dict(observed.entries)
                path = "/target" if phase == "runtime" else "/"
                entries[path] = replace(entries[path], mtime_ns=entries[path].mtime_ns - 1000000000)
                expected = oci_rootfs.OciRootfsManifest(entries, "a" * 64, "sha256:" + "b" * 64, "sha256:" + "c" * 64, (), ())
                baseline = len(os.listdir("/proc/self/fd"))
                watches = []
                class Watch:
                    def __init__(self, *args, **kwargs):
                        self.fd = os.open("/dev/null", os.O_RDONLY)
                        watches.append(self)
                    def __enter__(self): return self
                    def __exit__(self, *args): self.close()
                    def idle(self): pass
                    def finish(self): pass
                    def retire_displaced_inodes(self): pass
                    def close(self):
                        fd, self.fd = self.fd, -1
                        if fd >= 0: os.close(fd)
                try:
                    needle = "runtime_targets=(path,)) as operation_watch:" if phase == "runtime" else "directory_mtimes=(path,)) as operation_watch:"
                    with mock.patch.object(oci_rootfs._RepairParentWatch, "open", side_effect=Watch), self._registration_fault(oci_rootfs.normalize_vfs_materialization, needle, "LOAD_SPECIAL", occurrence=0) as primary:
                        with self.assertRaises(BaseException) as caught:
                            oci_rootfs.normalize_vfs_materialization(root, expected, runtime_bind_targets=("/target",) if phase == "runtime" else ())
                    self.assertIs(caught.exception, primary)
                    # Only the earlier long-lived watch may exist: the lazy
                    # operation factory has not run at LOAD_SPECIAL.
                    self.assertEqual(len(watches), 1)
                    self.assertTrue(all(watch.fd == -1 for watch in watches))
                    self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
                finally:
                    for watch in watches: watch.close()

