    def test_cleanup_source_markers_and_close_bytecode_have_no_detached_action_plans(self) -> None:
        import ast
        import dis
        import types
        modules = ("proof_io", "container_runtime", "kernel_bootstrap", "kernel_build", "oci_rootfs", "rpm_artifacts", "module_key")
        for module in modules:
            path = REPO / "tools/gate01" / f"{module}.py"
            source = path.read_text()
            tree = ast.parse(source)
            parents = {child: parent for parent in ast.walk(tree) for child in ast.iter_child_nodes(parent)}
            for node in ast.walk(tree):
                if not isinstance(node, ast.Call): continue
                if isinstance(node.func, ast.Name) and node.func.id == "_release_preserving_primary" and node.args:
                    self.assertFalse(any(isinstance(value, (ast.Lambda, ast.GeneratorExp, ast.ListComp, ast.List, ast.Tuple)) for value in ast.walk(node.args[0])), (module, node.lineno))
                if isinstance(node.func, ast.Name) and node.func.id == "_release_all" and node.args and isinstance(node.args[0], ast.GeneratorExp):
                    current = node
                    while not isinstance(current, ast.FunctionDef): current = parents[current]
                    self.assertEqual((module, current.name), ("container_runtime", "verify_cleanup_scope"))
                if isinstance(node.func, ast.Attribute) and node.func.attr == "add_note":
                    self.assertEqual(ast.unparse(node.func), "BaseException.add_note")
                    current = node
                    while not isinstance(current, ast.FunctionDef): current = parents[current]
                    self.assertEqual(current.name, "_add_cleanup_note")
            pending = [compile(source, str(path), "exec")]
            while pending:
                code = pending.pop()
                pending.extend(value for value in code.co_consts if isinstance(value, types.CodeType))
                if code.co_name == "close":
                    forbidden = {"BUILD_LIST", "BUILD_MAP", "BUILD_SET", "BUILD_TUPLE", "MAKE_FUNCTION", "LIST_APPEND", "SET_ADD", "MAP_ADD"}
                    self.assertFalse([(op.opname, op.starts_line) for op in dis.get_instructions(code) if op.opname in forbidden], (module, code.co_qualname))

