    def test_actual_code_authority_adopts_object_before_fallible_close_binding(self) -> None:
        primary = MemoryError("injected close method binding")
        baseline = len(os.listdir("/proc/self/fd"))
        class Resource:
            def __init__(self):
                self.fd = os.open("/dev/null", os.O_RDONLY)
                self.reject = True
            def __getattribute__(self, name):
                if name == "close" and object.__getattribute__(self, "reject"):
                    object.__setattr__(self, "reject", False)
                    raise primary
                return object.__getattribute__(self, name)
            def close(self):
                fd, self.fd = self.fd, -1
                if fd >= 0: os.close(fd)
        resource = Resource()
        inputs = mock.MagicMock()
        inputs.__enter__.return_value = inputs
        try:
            with mock.patch.object(kernel_build, "_EXECUTED_BOOTSTRAP_AUTHORITY", {}), mock.patch.object(kernel_build, "_EXECUTED_BOOTSTRAP_CAPSULE_SHA256", "a" * 64), mock.patch.object(kernel_build, "_EXECUTED_BOOTSTRAP_AUTHORITY_SHA256", "b" * 64), mock.patch.object(kernel_build.BoundInputs, "open", return_value=inputs), mock.patch.object(kernel_build, "_input_policies", return_value={}), mock.patch.object(kernel_build, "_executed_capsule_from_bound_inputs", return_value=resource):
                with self.assertRaises(BaseException) as caught:
                    with kernel_build._production_code_authority(Path("/inert")): pass
            self.assertIs(caught.exception, primary)
            self.assertEqual(resource.fd, -1)
            self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
        finally:
            resource.reject = False
            resource.close()

