    def test_bootstrap_remaining_close_helper_entries_keep_local_numeric_custody(self) -> None:
        from tools.gate01 import kernel_bootstrap as bootstrap
        for phase in ("verify", "seal", "capsule", "source-append", "target-append"):
            with self.subTest(phase=phase):
                baseline = len(os.listdir("/proc/self/fd"))
                primary = ValueError("injected bootstrap guarded body")
                acquired, attempted = [], []
                close, helper, control = os.close, bootstrap._close_two, fcntl.fcntl
                memfd, open_parent = os.memfd_create, bootstrap._open_parent
                record = None
                replaced = False
                class RejectAppend(list):
                    def append(self, value):
                        if len(self) == (0 if phase == "source-append" else 1):
                            raise primary
                        list.append(self, value)
                def creating(*args, **kwargs):
                    fd = memfd(*args, **kwargs)
                    acquired.append(fd)
                    return fd
                def reopening(*args):
                    fd, status = open_parent(*args)
                    acquired.append(fd)
                    return fd, status
                def controlling(fd, operation, *args):
                    nonlocal replaced
                    value = control(fd, operation, *args)
                    if operation == fcntl.F_DUPFD_CLOEXEC:
                        acquired.append(value)
                        if not replaced:
                            frame = sys._getframe()
                            while frame.f_code is not bootstrap._install_inheritable.__code__:
                                frame = frame.f_back
                            frame.f_locals["transient"] = RejectAppend()
                            replaced = True
                    return value
                def closing(fd):
                    if fd in acquired: attempted.append(fd)
                    close(fd)
                def failed_helper(*args, **kwargs):
                    if phase == "capsule" and args[0] not in acquired:
                        return helper(*args, **kwargs)
                    raise MemoryError("injected bootstrap close helper entry")
                try:
                    with contextlib.ExitStack() as patches:
                        if phase == "verify":
                            record = bootstrap._open_source(REPO, "tools/gate01/kernel_bootstrap.py")
                            patches.enter_context(mock.patch.object(bootstrap, "_open_parent", side_effect=reopening))
                            patches.enter_context(mock.patch.object(bootstrap, "_identity", side_effect=primary))
                            call = record.verify
                        elif phase == "seal":
                            patches.enter_context(mock.patch.object(os, "memfd_create", side_effect=creating))
                            patches.enter_context(mock.patch.object(os, "fsync", side_effect=primary))
                            call = lambda: bootstrap._seal_bytes("public-fixture", b"public")
                        elif phase == "capsule":
                            inherited = patches.enter_context((REPO / "tools/gate01/kernel_bootstrap.py").open("rb"))
                            patches.enter_context(mock.patch.object(os, "memfd_create", side_effect=creating))
                            patches.enter_context(mock.patch.object(bootstrap, "BootstrapCapsule", side_effect=primary))
                            call = lambda: bootstrap.build_bootstrap_capsule(REPO, inherited.fileno())
                        else:
                            source = patches.enter_context(tempfile.TemporaryFile())
                            target = patches.enter_context(tempfile.TemporaryFile())
                            original_target = os.fstat(target.fileno())
                            patches.enter_context(mock.patch.object(fcntl, "fcntl", side_effect=controlling))
                            call = lambda: bootstrap._install_inheritable({target.fileno(): source.fileno()})
                        patches.enter_context(mock.patch.object(bootstrap, "_close_two", side_effect=failed_helper))
                        patches.enter_context(mock.patch.object(os, "close", side_effect=closing))
                        with self.assertRaises(BaseException) as caught: call()
                        self.assertIs(caught.exception, primary)
                        self.assertCountEqual(attempted, acquired)
                        for fd in acquired:
                            with self.assertRaises(OSError) as absent: os.fstat(fd)
                            self.assertEqual(absent.exception.errno, errno.EBADF)
                        if phase.endswith("append"):
                            self.assertEqual(os.fstat(target.fileno()), original_target)
                    if record is not None:
                        record.close()
                        record = None
                    self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
                finally:
                    if record is not None: record.close()
                    for fd in acquired:
                        try: close(fd)
                        except OSError as error:
                            if error.errno != errno.EBADF: raise

    def test_bootstrap_restoration_and_main_note_entries_preserve_primary_and_siblings(self) -> None:
        from tools.gate01 import kernel_bootstrap as bootstrap
        for phase in ("restore-selection", "restore-operation", "main-identity", "main-final"):
            with self.subTest(phase=phase):
                baseline = len(os.listdir("/proc/self/fd"))
                primary = ValueError("injected bootstrap transition failure")
                acquired, attempted, notes = [], [], []
                close, dup2, flag, control, fstat = os.close, os.dup2, os.set_inheritable, fcntl.fcntl, os.fstat
                restoring = False
                class RejectPop(list):
                    def pop(self): raise MemoryError("injected restoration selection")
                def flagging(fd, value):
                    nonlocal restoring
                    if fd == 71:
                        restoring = True
                        if phase == "restore-selection":
                            frame = sys._getframe()
                            while frame.f_code is not bootstrap._install_inheritable.__code__:
                                frame = frame.f_back
                            frame.f_locals["installed"] = RejectPop(frame.f_locals["installed"])
