    def test_opaque_resource_mapping_retains_failed_owner_and_continues_siblings(self) -> None:
        class Owner:
            def __init__(self, fail):
                self.fd = os.open("/dev/null", os.O_RDONLY)
                self.fail = fail
                self.attempts = 0
            def close(self):
                self.attempts += 1
                if self.fail: raise MemoryError("persistent opaque close pre-entry failure")
                closing, self.fd = self.fd, -1
                if closing >= 0: os.close(closing)
        baseline = len(os.listdir("/proc/self/fd"))
        failed, sibling = Owner(True), Owner(False)
        resources = {"failed": failed, "sibling": sibling}
        primary = ValueError("injected caller primary")
        try:
            proof_io._close_resource_mapping(resources, primary)
            self.assertEqual(resources, {"failed": failed})
            self.assertLessEqual(failed.attempts, 3)
            self.assertEqual(sibling.fd, -1)
            self.assertEqual(primary.__notes__, ["additional bound descriptor cleanup failed"])
            self.assertEqual(len(os.listdir("/proc/self/fd")), baseline + 1)
            failed.fail = False
            proof_io._close_resource_mapping(resources)
            self.assertEqual(resources, {})
            self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
        finally:
            failed.fail = False
            failed.close()
            sibling.close()

