    def test_cleanup_snapshot_faults_never_replace_primary_or_lose_owned_resources(self) -> None:
        import inspect
        from tools.gate01 import module_key
        phases = ("anonymous-create", "slots-create", "anonymous-reopen", "slots-reopen", "fixed", "public-tree", "evidence", "certificate", "stream")
        for phase in phases:
            with self.subTest(phase=phase), tempfile.TemporaryDirectory() as name:
                root = Path(name)
                primary = ValueError("injected cleanup body primary")
                original_open, original_fcntl = os.open, fcntl.fcntl
                opened, owners = [], []
                attempts = 0
                def opening(path, flags, *args, **kwargs):
                    nonlocal attempts
                    selected = bool(flags & os.O_TMPFILE == os.O_TMPFILE) if phase.endswith("create") else str(path).startswith("/proc/self/fd/")
                    if selected:
                        attempts += 1
                        if attempts == 3: raise primary
                    fd = original_open(path, flags, *args, **kwargs)
                    opened.append(fd)
                    return fd
                def controlling(fd, operation, *args):
                    result = original_fcntl(fd, operation, *args)
                    if operation == fcntl.F_DUPFD_CLOEXEC: opened.append(result)
                    return result
                baseline = len(os.listdir("/proc/self/fd"))
                try:
                    with contextlib.ExitStack() as patches:
                        if phase.startswith(("anonymous", "slots")):
                            kind = proof_io.AnonymousOutputs if phase.startswith("anonymous") else proof_io.ArtifactSlots
                            if phase.endswith("create"):
                                function, needle, opcode = kind.create.__func__, "owned = tuple(descriptors.values())", "CALL"
                                call = (lambda: kind.create(root, ("a", "b", "c"))) if kind is proof_io.AnonymousOutputs else lambda: kind.create(root)
                            else:
                                owner = kind.create(root, ("a", "b", "c")) if kind is proof_io.AnonymousOutputs else kind.create(root)
                                owners.append(owner)
                                for fd in owner._descriptors.values(): os.write(fd, b"public")
                                if kind is proof_io.AnonymousOutputs:
                                    function, needle = kind.reopen_read_only, "owned = tuple(reopened.values())"
                                    call = lambda: owner.reopen_read_only(process_probe=lambda expected: None, lease_acquirer=lambda fd: None)
                                else:
                                    function, needle = kind.transition_to_read_only, "owned = tuple(read_only.values())"
                                    call = lambda: owner.transition_to_read_only(process_probe=lambda expected: None, lease_acquirer=lambda fd: None)
                                opcode = "CALL"
                            patches.enter_context(mock.patch.object(os, "open", side_effect=opening))
                        elif phase == "fixed":
                            source = patches.enter_context(tempfile.TemporaryFile())
                            target = patches.enter_context(tempfile.TemporaryFile())
                            owner = proof_io.FixedDescriptors({target.fileno(): source.fileno(), 70: source.fileno()})
                            function, needle, opcode = type(owner).__enter__, "descriptors = tuple(temporary.values())", "CALL"
                            call = owner.__enter__
                            patches.enter_context(mock.patch.object(os, "dup2", side_effect=primary))
                            patches.enter_context(mock.patch.object(fcntl, "fcntl", side_effect=controlling))
                        elif phase == "public-tree":
                            root.chmod(0o755)
                            (root / "public").write_bytes(b"public")
                            (root / "public").chmod(0o644)
                            function, needle, opcode = proof_io._bound_public_tree.__wrapped__, "actions = ([] if files is None", "BUILD_LIST"
                            def call():
                                with proof_io._bound_public_tree(root, {"public": hashlib.sha256(b"public").hexdigest()}, expected_uid=os.geteuid(), expected_gid=os.getegid()): raise primary
                        elif phase == "evidence":
                            function, needle, opcode = proof_io.publish_evidence_file, "actions = tuple(lambda fd=fd", "BUILD_LIST"
                            def body(): raise primary
                            call = lambda: proof_io.publish_evidence_file(b'{"verdict":"pass"}', final=root / "proof.json", receipt=root / "receipt.json", kind="comparison", input_sha256={"public": "a" * 64}, before_receipt=body, expected_uid=os.geteuid(), expected_gid=os.getegid())
                        elif phase == "certificate":
                            public = root / "public.pem"
                            public.write_bytes(b"inert public certificate fixture")
                            function, needle, opcode = module_key.describe, "actions = []", "BUILD_LIST"
                            patches.enter_context(mock.patch.object(module_key, "describe_descriptor", return_value={"schema_version": 1}))
                            patches.enter_context(mock.patch.object(module_key, "_write_all", side_effect=primary))
                            call = lambda: module_key.describe(public, root / "manifest.json")
                        else:
                            source = patches.enter_context(tempfile.TemporaryFile())
                            function, needle, opcode = rpm_artifacts._borrowed_binary_stream.__wrapped__, "actions = ([] if stream is None", "BUILD_LIST"
                            def call():
                                with rpm_artifacts._borrowed_binary_stream(source.fileno()): raise primary
                        if phase in {"public-tree", "evidence", "certificate"}: patches.enter_context(mock.patch.object(os, "open", side_effect=opening))
                        original_dup = os.dup
                        def duplicate(fd):
                            result = original_dup(fd)
                            opened.append(result)
                            return result
                        patches.enter_context(mock.patch.object(os, "dup", side_effect=duplicate))
                        # Removal of the aggregate construction removes this
                        # allocation boundary; retain the body-failure proof.
                        fault = self._registration_fault(function, needle, opcode) if needle in inspect.getsource(function) else contextlib.nullcontext()
                        with fault:
                            with self.assertRaises(BaseException) as caught: call()
                        self.assertIs(caught.exception, primary)
                    for owner in owners: owner.close()
                    owners.clear()
                    self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
                    self.assertFalse(list(root.glob(".*.part")))
                    self.assertFalse((root / "receipt.json").exists())
                finally:
                    for owner in owners: owner.close()
                    for fd in set(opened):
                        try: os.close(fd)
                        except OSError as error:
                            if error.errno != errno.EBADF: raise

