    def test_store_close_plan_and_late_target_transfer_keep_retryable_ownership(self) -> None:
        primary = MemoryError("injected final store ownership boundary")
        class RejectValues(dict):
            def __iter__(self): raise primary
            def values(self): raise primary
            def popitem(self): raise primary
        class RejectTargetStatus(container_runtime.BoundStorePath):
            reject = False
            def __setattr__(self, name, value):
                if name == "target_status" and self.reject: raise primary
                super().__setattr__(name, value)
        with tempfile.TemporaryDirectory() as name:
            root = Path(name)
            baseline = len(os.listdir("/proc/self/fd"))
            policy = container_runtime.SealedPodmanPolicy.create()
            store = PodmanStore(root / "store", environment={}, policy=policy)
            scratch = container_runtime.BoundScratch.open(root)
            binding = RejectTargetStatus.open(label="target", path=root / "target", root=scratch, expected_kind="regular", allow_missing=True)
            try:
                store.initialize()
                original = store._directory_bindings
                store._directory_bindings = RejectValues(original)
                with self.assertRaises(BaseException) as caught: store.close_scope()
                self.assertIs(caught.exception, primary)
                self.assertTrue(store._scope_closed)
                self.assertTrue(all(value.closed for value in original.values()))
                store._directory_bindings = original
                store.close_scope()
                (root / "target").write_bytes(b"public")
                binding.reject = True
                with self.assertRaises(MemoryError) as caught: binding.bind_present_target()
                self.assertIs(caught.exception, primary)
                self.assertIsNone(binding.target_descriptor)
            finally:
                binding.reject = False
                store._directory_bindings = original
                store.close_scope()
                try: binding.close()
                except OSError as error:
                    if error.errno != errno.EBADF: raise
                scratch.close()
                policy.close()
            self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)

