    def test_close_plan_failure_remains_retryable_until_owned_fields_can_detach(self) -> None:
        from types import SimpleNamespace
        cases = ((proof_io.BoundInputs, "_records"), (proof_io.BoundScopedDiff, "_nodes"), (proof_io.AnonymousOutputs, "_descriptors"), (proof_io.BoundAcceptedTree, "_directories"), (container_runtime.WatchedRuntimeBindings, "_records"), (container_runtime.SealedPodmanPolicy, "_containers"), (container_runtime.BoundScratch, "descriptor"), (container_runtime.BoundStorePath, "target_descriptor"), (container_runtime.BoundLiveProcess, "root_fd"), (kernel_build._BuilderWorkspace, "_lock_descriptor"), (kernel_build._ScopedTemporaryTree, "_root_descriptor"))
        for base, field in cases:
            with self.subTest(owner=base.__name__), tempfile.TemporaryDirectory() as name:
                root = os.open(name, os.O_RDONLY | os.O_DIRECTORY)
                baseline = len(os.listdir("/proc/self/fd"))
                owned = [os.dup(root) for _ in range(4)]
                primary = MemoryError("injected close plan formation")
                class Owner(base):
                    def __getattribute__(self, key):
                        if key == field and object.__getattribute__(self, "armed"):
                            object.__setattr__(self, "armed", False)
                            raise primary
                        return super().__getattribute__(key)
                owner = object.__new__(Owner)
                owner.armed = False
                owner._closed = owner.closed = False
                if base is proof_io.BoundInputs:
                    owner._records = {
                        "one": SimpleNamespace(descriptor=owned[0], parent_descriptor=owned[1]),
                        "two": SimpleNamespace(descriptor=owned[2], parent_descriptor=owned[3]),
                    }
                elif base is proof_io.BoundScopedDiff: owner._nodes, owner._parent = {str(i): {"fd": fd} for i, fd in enumerate(owned[:3])}, owned[3]
                elif base is proof_io.AnonymousOutputs: owner._descriptors, owner._read_descriptors = {str(i): fd for i, fd in enumerate(owned)}, {}
                elif base is proof_io.BoundAcceptedTree:
                    owner._directories = {"one": SimpleNamespace(descriptor=owned[0]), "two": SimpleNamespace(descriptor=owned[1])}
                    owner._files = object.__new__(proof_io.BoundInputs)
                    owner._files._closed = False
                    owner._files._records = {"one": SimpleNamespace(descriptor=owned[2], parent_descriptor=owned[3])}
                elif base is container_runtime.WatchedRuntimeBindings: owner._records, owner._parents_by_watch, owner._watch_descriptor = {"one": SimpleNamespace(descriptor=owned[0]), "two": SimpleNamespace(descriptor=owned[1])}, {"one": SimpleNamespace(descriptor=owned[2])}, owned[3]
                elif base is container_runtime.SealedPodmanPolicy:
                    owner._containers = proof_io.SealedCapsule(owned[0], "a" * 64, 0)
                    owner._storage = proof_io.SealedCapsule(owned[1], "b" * 64, 0)
                    for fd in owned[2:]: os.close(fd)
                    owned = owned[:2]
                elif base is container_runtime.BoundScratch:
                    owner.descriptor, owner.parent_descriptor = owned[:2]
                    for fd in owned[2:]: os.close(fd)
                    owned = owned[:2]
                elif base is container_runtime.BoundStorePath: owner.target_descriptor, owner.owned_directories = owned[0], list(owned[1:])
                elif base is container_runtime.BoundLiveProcess: owner.root_fd, owner.proc_fd, owner.proc_parent_fd, owner.pidfd = owned
                elif base is kernel_build._BuilderWorkspace: owner._lock_descriptor, owner._directory_descriptors = owned[0], tuple(owned[1:])
                else:
                    owner._root_descriptor, owner._parent_descriptor = owned[:2]
                    for fd in owned[2:]: os.close(fd)
                    owned = owned[:2]
                owner.armed = True
                try:
                    with self.assertRaises(BaseException) as caught: owner.close()
                    self.assertIs(caught.exception, primary)
                    self.assertFalse(owner._closed or owner.closed)
                    for fd in owned: os.fstat(fd)
                    owner.close()
                    owner.close()
                    self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)
                finally:
                    for fd in owned:
                        try: os.close(fd)
                        except OSError as error:
                            if error.errno != errno.EBADF: raise
                    os.close(root)

    def test_exit_stack_adoption_failure_unwinds_current_resource_and_keeps_prior_order(self) -> None:
        from collections import deque
        for kind in ("context", "callback"):
            for cleanup_failure in (False, True):
                with self.subTest(kind=kind, cleanup_failure=cleanup_failure):
                    primary = MemoryError("injected callback adoption")
                    events = []
                    class Rejecting(deque):
                        def append(self, value): raise primary
                    class Resource:
                        def __enter__(self): events.append("enter"); return self
                        def __exit__(self, *args): self.close()
                        def close(self):
                            events.append("close")
                            if cleanup_failure: raise OSError(errno.EIO, "/sensitive/close")
                    with kernel_build._PrimaryExitStack() as stack:
                        stack.callback(events.append, "prior")
                        stack._exit_callbacks = Rejecting(stack._exit_callbacks)
                        with self.assertRaises(BaseException) as caught:
                            if kind == "context": stack.enter_context(Resource())
                            else: stack.callback(Resource().close)
                        self.assertIs(caught.exception, primary)
                        self.assertEqual(events, (["enter"] if kind == "context" else []) + ["close"])
                        if cleanup_failure: self.assertTrue(primary.__notes__)
                    self.assertEqual(events[-1], "prior")

    @contextlib.contextmanager
    def _registration_fault(self, function, needle, opcode="CALL", occurrence=-1):
        primary = MemoryError("injected ownership registration")
        lines, start = inspect.getsourcelines(function)
        selected = {start + index for index, line in enumerate(lines) if needle in line}
        codes = []
        def descend(code):
            codes.append(code)
            for value in code.co_consts:
                if inspect.iscode(value): descend(value)
        descend(function.__code__)
        offsets = {}
        for code in codes:
            matches = [item for item in dis.get_instructions(code) if (item.opname.startswith("CALL") if opcode == "CALL_ANY" else item.opname == opcode) and item.positions.lineno in selected]
            if matches:
                offsets[code] = {item.offset for item in matches} if occurrence is None else {sorted(item.offset for item in matches)[occurrence]}
        self.assertTrue(offsets, (function, needle, opcode))
        fired = False
        def trace(frame, event, argument):
            nonlocal fired
            if frame.f_code in offsets:
                frame.f_trace_opcodes = True
                if event == "opcode" and frame.f_lasti in offsets[frame.f_code]:
                    fired = True
                    raise primary
            return trace
        try:
            sys.settrace(trace)
            yield primary
        finally:
            sys.settrace(None)
            self.assertTrue(fired)

