    def test_output_and_fixed_role_registration_faults_have_immediate_owners(self) -> None:
        def descriptors():
            result = set()
            for value in os.listdir("/proc/self/fd"):
                try: os.fstat(int(value))
                except OSError as error:
                    if error.errno != errno.EBADF: raise
                else: result.add(value)
            return result
        cases = (("anonymous-create", "descriptors[role] =", "STORE_SUBSCR"), ("artifact-create", "descriptors[role] =", "STORE_SUBSCR"), ("anonymous-read", "reopened[role] =", "STORE_SUBSCR"), ("artifact-read", "read_only[role] =", "STORE_SUBSCR"), ("fixed-save", "self._saved[target] = (saved", "STORE_SUBSCR"), ("fixed-temp", "temporary[target] =", "STORE_SUBSCR"), ("fixed-install", "self._installed.add(target)", "CALL"))
        for phase, needle, opcode in cases:
            with self.subTest(phase=phase), tempfile.TemporaryDirectory() as name:
                primary = MemoryError("injected resource transfer opcode")
                before = descriptors()
                try:
                    with contextlib.ExitStack() as owners:
                        if phase.startswith("anonymous"):
                            function = proof_io.AnonymousOutputs.create.__func__ if phase.endswith("create") else proof_io.AnonymousOutputs.reopen_read_only
                            if phase.endswith("create"):
                                call = lambda: proof_io.AnonymousOutputs.create(Path(name), ("one", "two"))
                            else:
                                output = proof_io.AnonymousOutputs.create(Path(name), ("one", "two"))
                                owners.callback(output.close)
                                for fd in output._descriptors.values(): os.write(fd, b"public")
                                call = lambda: output.reopen_read_only(process_probe=lambda _: None, lease_acquirer=lambda _: None)
                        elif phase.startswith("artifact"):
                            function = proof_io.ArtifactSlots.create.__func__ if phase.endswith("create") else proof_io.ArtifactSlots.transition_to_read_only
                            if phase.endswith("create"):
                                call = lambda: proof_io.ArtifactSlots.create(Path(name))
                            else:
                                output = proof_io.ArtifactSlots.create(Path(name))
                                owners.callback(output.close)
                                for fd in output._descriptors.values(): os.write(fd, b"public")
                                call = lambda: output.transition_to_read_only(process_probe=lambda _: None, lease_acquirer=lambda _: None)
                        else:
                            function = proof_io.FixedDescriptors.__enter__
                            descriptor = os.open(name, os.O_RDONLY | os.O_DIRECTORY)
                            owners.callback(os.close, descriptor)
                            target = max(map(int, os.listdir("/proc/self/fd"))) + 64
                            os.dup2(descriptor, target, inheritable=False)
                            owners.callback(os.close, target)
                            original_target = os.fstat(target)
                            mapping = proof_io.FixedDescriptors({target: descriptor})
                            call = mapping.__enter__
                        lines, start = inspect.getsourcelines(function)
                        selected = {start + index for index, line in enumerate(lines) if needle in line}
                        offsets = {item.offset for item in dis.get_instructions(function) if item.opname == opcode and item.positions.lineno in selected}
                        self.assertTrue(offsets)
                        fired = False
                        def trace(frame, event, argument):
                            nonlocal fired
                            if frame.f_code is function.__code__:
                                frame.f_trace_opcodes = True
                                if event == "opcode" and frame.f_lasti in offsets:
                                    fired = True
                                    raise primary
                            return trace
                        try:
                            sys.settrace(trace)
                            with self.assertRaises(BaseException) as caught: call()
                        finally: sys.settrace(None)
                        self.assertTrue(fired)
                        self.assertIs(caught.exception, primary)
                        if phase.startswith("fixed"):
                            self.assertEqual(os.fstat(target), original_target)
                            self.assertFalse(os.get_inheritable(target))
                    self.assertEqual(descriptors(), before)
                finally:
                    for value in descriptors() - before:
                        try: os.close(int(value))
                        except OSError as error:
                            if error.errno != errno.EBADF: raise

