    def test_actual_probe_and_meta_callers_release_failed_backend_and_store_scopes(self) -> None:
        for caller in ("probe", "meta"):
            for store_failure in (False, True):
                for close_failure in (False, True):
                    with self.subTest(caller=caller, store_failure=store_failure, close_failure=close_failure), NoBuildEvidenceTests()._probe() as (repository, events, _):
                        primary = ValueError("injected caller backend verification")
                        original_open, original_close = container_runtime.BoundScratch.open, os.close
                        bindings, stores, scratch_fds, closes = [], [], [], []
                        def opening(path, **kwargs):
                            bound = original_open(path, **kwargs)
                            bindings.append(bound)
                            if Path(path).name == "scratch":
                                scratch_fds.extend((bound.descriptor, bound.parent_descriptor))
                                bound.verify = lambda: (_ for _ in ()).throw(primary)
                            return bound
                        def store_factory(*args, **kwargs):
                            store = container_runtime.PodmanStore(*args, **kwargs)
                            stores.append(store)
                            return store
                        def run(store, arguments, **kwargs):
                            import shutil
                            if not store_failure:
                                base = store._directory_bindings["store-base"].descriptor
                                for child in ("root", "runroot", "tmp"):
                                    shutil.rmtree(child, dir_fd=base)
                            return subprocess.CompletedProcess([], int(store_failure), b"", b"")
                        def close(fd):
                            original_close(fd)
                            if fd in scratch_fds and len(closes) < 2:
                                closes.append(fd)
                                if close_failure and len(closes) == 1: raise OSError(errno.EIO, "/sensitive/close")
                        baseline = len(os.listdir("/proc/self/fd"))
                        with mock.patch.object(kernel_build, "PodmanStore", side_effect=store_factory), mock.patch.object(kernel_build, "PodmanContainerBackend", container_runtime.PodmanContainerBackend), mock.patch.object(container_runtime.BoundScratch, "open", side_effect=opening), mock.patch.object(container_runtime.PodmanStore, "import_image"), mock.patch.object(container_runtime.PodmanStore, "run", autospec=True, side_effect=run) as command:
                            with mock.patch.object(kernel_build, "_remove_podman_store", container_runtime._remove_podman_store), mock.patch.dict(kernel_build._cleanup_meta_resources.__kwdefaults__, {"remove_store": container_runtime._remove_podman_store}), mock.patch.object(os, "close", side_effect=close), mock.patch.object(kernel_build, "run_container_lifecycle", side_effect=AssertionError("lifecycle forbidden")) as lifecycle:
                                with self.assertRaises(BaseException) as caught:
                                    if caller == "probe": kernel_build.run_no_build_lifecycle(repository)
                                    else: kernel_build._query_meta_requirements_in_fresh_container(repository, 30, "builder-a")
                        self.assertIs(caught.exception, primary)
                        self.assertEqual(closes, scratch_fds)
                        self.assertTrue(all(binding.closed for binding in bindings))
                        self.assertTrue(all(store._scope_closed and not store.base.exists() for store in stores))
                        self.assertEqual(len(stores), 1)
                        self.assertTrue(command.called)
                        lifecycle.assert_not_called()
                        self.assertIn("temporary-remove", events)
                        if store_failure or close_failure:
                            self.assertTrue(primary.__notes__)
                            self.assertNotIn("sensitive", str(primary.__notes__))
                        self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)

