            original_hash, original_close = container_runtime._hash_descriptor, os.close
            targets = []
            def hashing(fd):
                nonlocal calls
                calls += 1
                targets.append(fd)
                if calls == 3: raise primary
                return original_hash(fd)
            attempts = []
            def closing(fd):
                original_close(fd)
                if fd in targets:
                    attempts.append(fd)
                    raise OSError(errno.EIO, "injected watched cleanup")
            baseline = len(os.listdir("/proc/self/fd"))
            with mock.patch.object(container_runtime, "_hash_descriptor", side_effect=hashing), mock.patch.object(os, "close", side_effect=closing):
                with self.assertRaises(Exception) as caught: container_runtime.WatchedRuntimeBindings.open({name: root / name for name in ("a", "b", "c")})
            self.assertIs(caught.exception, primary)
            self.assertTrue(caught.exception.__notes__)
            self.assertCountEqual(attempts, targets)
            self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)

