    def test_every_normative_plan_descriptor_and_redaction_contract_is_current(self) -> None:
        plan = (REPO / "docs/superpowers/plans/2026-09-03-stone-boot-proof.md").read_text()
        readme = (REPO / "os/kernel/README.md").read_text()
        self.assertIn("an unproven or nonzero command outcome", readme)
        self.assertNotIn("a raised or nonzero command", readme)
        inspector = next(line for line in plan.splitlines() if line.startswith("`tools/gate01/rpm_artifacts.py inspect-fixed-fds` receives only"))
        self.assertIn("`42`", inspector)
        build = next(line for line in plan.splitlines() if line.startswith("6. Create four anonymous"))
        self.assertIn("`20`-`26`", build)
        roles = next(line for line in plan.splitlines() if line.startswith("- a deterministic, fully sealed verifier capsule;"))
        self.assertIn("`26` (build result)", roles)
        self.assertNotIn("offending relative paths", plan)
        start = plan.index("**Step 9: Run the no-build verification and fresh review gate**")
        finish = plan.index("**Step 10: Build twice", start)
        self.assertEqual(plan.count("The no-build evidence commits schema version 1"), 1)
        self.assertIn("The no-build evidence commits schema version 1", plan[start:finish])
        self.assertIn("fixed redacted diagnostic", plan)
        self.assertIn("fixed redacted cleanup notes", readme)
        try:
            brief = (REPO / ".superpowers/sdd/2026-09-03-stone-boot-proof/task-6-brief.md").read_text()
        except FileNotFoundError:
            brief = None  # Ignored coordination material is absent in clean checkouts.
        if brief is not None:
            for label, selector, required in (
                ("Step 1 roles", "- a deterministic, fully sealed verifier capsule;", "`26` (build result)"),
                ("Step 5 inspector", "`tools/gate01/rpm_artifacts.py inspect-fixed-fds` receives only", "`42` (structured inspection result)"),
                ("Step 6 build", "6. Create four anonymous", "`20`-`26`"),
            ):
                with self.subTest(brief_contract=label):
                    statement = next(line for line in brief.splitlines() if line.startswith(selector))
                    self.assertIn(required, statement)
            with self.subTest(brief_contract="redaction"):
                self.assertNotIn("emits only offending relative paths", brief)
                self.assertIn("fixed redacted diagnostic", brief)
        for role, fds in (("build", "20–26"), ("inspect", "FD40/41/42")):
            self.assertIn(fds, plan, role)

