                    with self.assertRaises(Exception) as caught:
                        rpm_artifacts._inspect_rpm_descriptors_in_root(dict.fromkeys(("srpm", "core", "modules", "meta"), artifact.fileno()), extract_root=root, extract_root_descriptor=parent, public_certificate_descriptor=artifact.fileno(), expected_source_payload_sha256={})
