    def test_container_remove_attempts_rm_and_scratch_after_config_close_failure(self) -> None:
        from types import SimpleNamespace
        for failure in ("config-verify", "config-close", "cleanup-scope", "missing-scope", "rm", "scratch"):
            with self.subTest(failure=failure):
                attempts = []
                def action(name):
                    attempts.append(name)
                    if name == failure: raise OSError(errno.EIO, "injected cleanup failure")
                backend = object.__new__(container_runtime.PodmanContainerBackend)
                backend._started = False
                backend._live_process = None
                backend._created = True
                backend._conmon_binding = None
                backend.container = "fixture"
                backend._config_inputs = SimpleNamespace(verify_coherent=lambda: action("config-verify"), close=lambda: action("config-close"))
                backend._scratch_binding = SimpleNamespace(verify=lambda: action("scratch"))
                backend.store = SimpleNamespace(verify_scope=lambda **kw: action("store-verify"), verify_cleanup_scope=lambda: action("cleanup-scope"), run=lambda args: action("rm"))
                if failure == "missing-scope": del backend.store.verify_cleanup_scope
                with self.assertRaises(Exception): backend.remove()
                expected = ["config-verify", "config-close", "store-verify"]
                if failure != "missing-scope": expected.append("cleanup-scope")
                if failure not in {"cleanup-scope", "missing-scope"}: expected.append("rm")
                self.assertEqual(attempts, [*expected, "scratch"])
                self.assertIsNone(backend._config_inputs)

