class NoBuildEvidenceTests(unittest.TestCase):
    def test_temporary_close_failure_prevents_no_build_pass_and_continues_cleanup(self) -> None:
        with self._probe() as (repository, events, authority):
            original = kernel_build._ScopedTemporaryTree.close
            actual_close = os.close
            attempted = []
            def closing(tree):
                targets = {tree._root_descriptor, tree._parent_descriptor}
                def close(fd):
                    actual_close(fd)
                    if fd in targets:
                        attempted.append(fd)
                        raise OSError(errno.EIO, "injected post-close failure")
                with mock.patch.object(kernel_build.os, "close", side_effect=close): original(tree)
            with mock.patch.object(kernel_build._ScopedTemporaryTree, "close", new=closing):
                with self.assertRaises(RuntimeError): kernel_build.run_no_build_lifecycle(repository)
            self.assertEqual(len(attempted), 2)
            self.assertIn("backend-close", events)
            self.assertEqual(list((repository / "build/gate01").glob(".kernel-lifecycle-*")), [])

    def test_meta_backend_close_failure_does_not_skip_policy_close_or_mask_primary(self) -> None:
        with self._probe() as (repository, events, authority), tempfile.TemporaryFile() as fixture:
            fixture.write(b"synthetic meta RPM")
            fixture.flush()
            descriptor = os.open(f"/proc/self/fd/{fixture.fileno()}", os.O_RDONLY | os.O_CLOEXEC)
            primary = ValueError("meta lifecycle interrupted")
            policy_close = container_runtime.SealedPodmanPolicy.close
            def closing(policy):
                events.append("policy-close")
                policy_close(policy)
            def lifecycle(backend, **kwargs):
                def backend_close():
                    events.append("backend-close-fault")
                    raise OSError(errno.EIO, "injected backend close")
                backend.close = backend_close
                raise primary
            try:
                with mock.patch.object(kernel_build, "run_container_lifecycle", side_effect=lifecycle), mock.patch.object(container_runtime.SealedPodmanPolicy, "close", new=closing):
                    with self.assertRaises(Exception) as caught:
                        kernel_build._query_meta_requirements_in_fresh_container(repository, descriptor, "builder-a")
                self.assertIs(caught.exception, primary)
                self.assertIn("backend-close-fault", events)
                self.assertEqual(events[-1], "policy-close")
            finally: os.close(descriptor)

    @contextlib.contextmanager
    def _probe(self, *, during_cleanup=None, cleanup_failure=None, corruption=None, initially_present: bool = False):
        from tools.gate01 import kernel_bootstrap
        import shutil
        with tempfile.TemporaryDirectory() as name, contextlib.ExitStack() as stack:
            repository = Path(name)
            for relative in kernel_build.BOOTSTRAP_SOURCE_PATHS:
                path = repository / relative
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_bytes((REPO / relative).read_bytes())
                path.chmod(0o755 if relative.endswith(".sh") else 0o644)
            fixture = repository / "tests/gate01/fixtures/oci-config-podman-5.7-crun-1.21.json"
            fixture.parent.mkdir(parents=True)
            fixture.write_bytes((REPO / fixture.relative_to(repository)).read_bytes())
            fixture.chmod(0o644)
            untracked = repository / "tests/gate01/untracked.py"
            untracked.write_bytes(b"original\n")
            untracked.chmod(0o644)
            archive = repository / "build/gate01/cache/kernel-builder.oci.tar"
            archive.parent.mkdir(parents=True)
            for parent in (archive.parent, archive.parent.parent, archive.parent.parent.parent):
                parent.chmod(0o755)
            archive.write_bytes(b"public OCI worker fixture")
            archive.chmod(0o644)
            source = ComparisonAndMetaProofTests._source_capsule()
            summary = source["oci_rootfs"]
            summary["archive_sha256"] = hashlib.sha256(archive.read_bytes()).hexdigest()
            lock = repository / "os/build/toolchain.lock.json"
            lock.parent.mkdir(parents=True)
            lock.write_bytes(proof_io._canonical_json({"schema_version": 1, "architecture": "x86_64", "image_reference": "fixture", "manifest_digest": summary["manifest_digest"], "archive_sha256": summary["archive_sha256"], "commands": {}, "installed_rpms": []}))
            lock.chmod(0o644)
            inherited = os.open(repository / "tools/gate01/kernel_bootstrap.py", os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
            try:
                capsule = kernel_bootstrap.build_bootstrap_capsule(repository, inherited)
            finally:
                os.close(inherited)
            stack.callback(capsule.close)
            authority = json.loads(proof_io._read_descriptor(capsule.authority_fd))
            stack.enter_context(FixedDescriptors({61: capsule.capsule_fd, 62: capsule.authority_fd}))
            for attribute, value in (("_EXECUTED_BOOTSTRAP_AUTHORITY", authority), ("_EXECUTED_BOOTSTRAP_CAPSULE_SHA256", capsule.capsule_sha256), ("_EXECUTED_BOOTSTRAP_AUTHORITY_SHA256", capsule.authority_sha256)):
                stack.enter_context(mock.patch.object(kernel_build, attribute, value))
            events = []
            case = self
            class Store:
                def __init__(self, base, **kwargs):
                    self.base = base
                def initialize(self):
                    self.base.mkdir()
                def import_image(self, descriptor, **kwargs):
                    case.assertEqual(proof_io._hash_descriptor(descriptor), summary["archive_sha256"])
            class Backend:
                def __init__(self, **kwargs):
                    self.store = kwargs["store"]
                    self.execution_results = {}
                    rootfs, contract = _runtime_evidence(
                        repository, "fixture", source, probe_root=self.store.base.parent,
                        initially_present_by_role={"build": initially_present, "inspection": False},
                    )
                    self.phase = rootfs["build"]["before"]
                    self.contract_record = contract["build"]
                    if corruption is not None:
                        corruption(self.contract_record, self.phase)
                def create(self): events.append("create")
                def initialize(self): events.append("initialize")
                def audit_effective_spec(self): events.append("spec")
                def audit_rootfs(self, phase): return copy.deepcopy(self.phase)
                def start(self): events.append("start")
                def attest_live(self): events.append("attest")
                def authorize_work(self): events.append("authorize")
                def execute(self, role, descriptors):
                    case.assertEqual(role, "probe")
                    case.assertEqual(set(descriptors), {20})
                    case.assertEqual(proof_io._hash_descriptor(descriptors[20]), capsule.capsule_sha256)
                    self.execution_results[role] = subprocess.CompletedProcess([], 0, b'{"verdict":"pass","verifier_fd":20}', b"")
                def stop_and_wait(self): events.append("stop")
                def remove(self):
                    events.append("container-remove")
                    if cleanup_failure == "container":
                        raise RuntimeError("injected container removal failure")
                def close(self): events.append("backend-close")
            def remove_store(store):
                events.append("store-remove")
                if during_cleanup is not None:
                    during_cleanup(repository)
                if cleanup_failure == "store":
                    raise RuntimeError("injected store removal failure")
                shutil.rmtree(store.base)
            real_remove = kernel_build._ScopedTemporaryTree.remove
            def remove_temporary(anchor):
                events.append("temporary-remove")
                real_remove(anchor)
                if cleanup_failure == "temporary":
                    raise RuntimeError("injected temporary removal failure")
            stack.enter_context(mock.patch.object(proof_io.subprocess, "run", return_value=subprocess.CompletedProcess([], 0, b"", b"")))
            stack.enter_context(mock.patch.object(kernel_build, "run_verifier_capsule", return_value=subprocess.CompletedProcess([], 0, proof_io._canonical_json(summary), b"")))
            stack.enter_context(mock.patch.object(kernel_build, "PodmanStore", Store))
            stack.enter_context(mock.patch.object(kernel_build, "PodmanContainerBackend", Backend))
            stack.enter_context(mock.patch.object(kernel_build, "_remove_podman_store", side_effect=remove_store))
            stack.enter_context(mock.patch.dict(kernel_build._cleanup_meta_resources.__kwdefaults__, {"remove_store": remove_store}))
            stack.enter_context(mock.patch.object(kernel_build._ScopedTemporaryTree, "remove", remove_temporary))
            yield repository, events, authority

    def test_real_bootstrap_authority_and_post_cleanup_scope_bind_passing_probe_evidence(self) -> None:
        with self._probe() as (repository, events, authority):
            result = kernel_build.run_no_build_lifecycle(repository)
            self.assertEqual(result.get("schema_version"), 1)
            self.assertEqual(result.get("bootstrap_authority"), authority)
            self.assertEqual(result.get("bootstrap_authority_sha256"), _object_sha256(authority))
            self.assertEqual(result.get("executed_capsule_sha256"), authority["capsule_sha256"])
            self.assertEqual(result.get("scoped_diff_sha256"), _object_sha256(result.get("scoped_diff")))
            self.assertEqual(result.get("cleanup"), {"container_removed": True, "store_removed": True, "temporary_tree_removed": True, "scope_revalidated_after_cleanup": True, "verdict": "pass"})
            self.assertEqual(events[-3:], ["store-remove", "temporary-remove", "backend-close"])
            self.assertEqual(list((repository / "build/gate01").glob(".kernel-lifecycle-*")), [])

