    def test_every_bound_resource_reports_close_fault_after_attempting_each_fd_once(self) -> None:
        from types import SimpleNamespace
        for kind in ("capsule", "secret", "descriptor", "artifacts", "slots", "outputs", "policy", "scratch", "store-path", "store-scope", "live-process", "runtime-inputs"):
            with self.subTest(kind=kind):
                initial = len(os.listdir("/proc/self/fd"))
                count = 1 if kind in {"capsule", "secret", "descriptor"} else 4 if kind in {"live-process", "store-scope"} else 3 if kind == "runtime-inputs" else 2
                descriptors = [os.memfd_create("public-release-fixture", os.MFD_CLOEXEC) for _ in range(count)]
                if kind == "capsule": resource = proof_io.SealedCapsule(descriptors[0], "0" * 64, 0)
                elif kind == "secret": resource = proof_io.SealedSecret(descriptors[0], 0)
                elif kind == "descriptor": resource = proof_io._DescriptorResource(descriptors[0])
                elif kind == "artifacts": resource = proof_io.ArtifactSet(dict(enumerate(descriptors)), {})
                elif kind == "slots": resource = proof_io.ArtifactSlots(dict(enumerate(descriptors)))
                elif kind == "outputs": resource = proof_io.AnonymousOutputs(dict(enumerate(descriptors)))
                elif kind == "policy":
                    for fd in descriptors:
                        os.close(fd)
                    resource = container_runtime.SealedPodmanPolicy.create()
                    descriptors = list(resource.descriptors)
                elif kind == "scratch":
                    resource = object.__new__(container_runtime.BoundScratch)
                    resource.closed = False
                    resource.descriptor, resource.parent_descriptor = descriptors
                elif kind == "store-path":
                    resource = object.__new__(container_runtime.BoundStorePath)
                    resource.closed = False
                    resource.target_descriptor, directory = descriptors
                    resource.owned_directories = [directory]
                elif kind == "store-scope":
                    store = object.__new__(container_runtime.PodmanStore)
                    store._scope_closed = False
                    store._reported_paths = {}
                    for label, descriptor in (("later", descriptors[1]), ("first", descriptors[0])):
                        binding = object.__new__(container_runtime.BoundStorePath)
                        binding.target_descriptor = descriptor
                        binding.owned_directories = []
                        binding.closed = False
                        store._reported_paths[label] = binding
                    scratch = object.__new__(container_runtime.BoundScratch)
                    scratch.descriptor, scratch.parent_descriptor = descriptors[2:]
                    scratch.closed = False
                    store._directory_bindings = {"store-base": scratch}
                    resource = SimpleNamespace(close=store.close_scope)
                elif kind == "live-process":
                    resource = object.__new__(container_runtime.BoundLiveProcess)
                    resource.closed = False
                    resource.root_fd, resource.proc_fd, resource.proc_parent_fd, resource.pidfd = descriptors
                else:
                    resource = object.__new__(container_runtime.WatchedRuntimeBindings)
                    resource._closed = False
                    resource._records = {"target": SimpleNamespace(descriptor=descriptors[0])}
                    resource._parents_by_watch = {1: SimpleNamespace(descriptor=descriptors[1])}
                    resource._watch_descriptor = descriptors[2]
                real_close, real_write = os.close, os.write
                closed, warnings = [], []
                def close(descriptor):
                    closed.append(descriptor)
                    real_close(descriptor)
                    if descriptor == descriptors[0]:
                        raise OSError(errno.EIO, "injected Linux post-close failure")
                def write(descriptor, value):
                    if descriptor == 2:
                        warnings.append(value)
                        return len(value)
                    return real_write(descriptor, value)
                with mock.patch.object(proof_io.os, "close", side_effect=close), mock.patch.object(proof_io.os, "write", side_effect=write):
                    proof_io._best_effort_release(resource.close)
                    first_closed = sorted(closed)
                    resource.close()
                self.assertEqual(first_closed, sorted(descriptors))
                self.assertEqual(sorted(closed), sorted(descriptors))
                self.assertEqual(warnings, [b"warning: post-receipt local cleanup or diagnostic failed\n"])
                self.assertEqual(len(os.listdir("/proc/self/fd")), initial)

