    @staticmethod
    def _fds_targeting(path: Path) -> list[str]:
        expected = str(path)
        targets: list[str] = []
        for entry in Path("/proc/self/fd").iterdir():
            try:
                target = os.readlink(entry)
            except FileNotFoundError:
                continue
            if target == expected:
                targets.append(target)
        return targets

