    def test_role_metadata_policy_rejects_wrong_mode_owner_or_link_count(self) -> None:
        policy_type = getattr(proof_io, "InputMetadataPolicy", None)
        self.assertIsNotNone(
            policy_type,
            "BoundInputs needs an explicit per-role metadata policy",
        )
        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            source = root / "source"
            source.write_bytes(b"trusted bytes\n")
            source.chmod(0o644)
            expected = policy_type(
                mode=0o644,
                uid=os.geteuid(),
                gid=os.getegid(),
                nlink=1,
            )
            with BoundInputs.open({"source": source}, policies={"source": expected}):
                pass

            for description, prepare in (
                ("mode", lambda: source.chmod(0o666)),
                ("hardlink", lambda: (root / "alias").hardlink_to(source)),
            ):
                source.chmod(0o644)
                alias = root / "alias"
                if alias.exists():
                    alias.unlink()
                prepare()
                with self.subTest(description=description), self.assertRaisesRegex(
                    ValueError, "metadata policy"
                ):
                    BoundInputs.open(
                        {"source": source}, policies={"source": expected}
                    )
            if (root / "alias").exists():
                (root / "alias").unlink()

            real_fstat = proof_io.os.fstat

            def foreign_owner(descriptor: int) -> os.stat_result:
                status = real_fstat(descriptor)
                fields = list(status)
                fields[4] = os.geteuid() + 1
                return os.stat_result(fields)

            with (
                mock.patch.object(proof_io.os, "fstat", side_effect=foreign_owner),
                self.assertRaisesRegex(ValueError, "metadata policy"),
            ):
                BoundInputs.open(
                    {"source": source}, policies={"source": expected}
                )
            self.assertEqual(self._fds_targeting(root), [])

            with (
                mock.patch.object(
                    proof_io.os,
                    "listdir",
                    side_effect=OSError("injected list failure"),
                ),
                self.assertRaisesRegex(OSError, "list failure"),
            ):
                BoundInputs.open(
                    {"source": source}, policies=_policies({"source": source})
                )
            self.assertEqual(self._fds_targeting(root), [])

    def test_transient_restore_and_inode_replacement_are_not_accepted(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            source = root / "source"
            source.write_bytes(b"trusted bytes\n")

            with BoundInputs.open(
                {"source": source}, policies=_policies({"source": source})
            ) as inputs:
                original = source.read_bytes()
                source.write_bytes(b"X" * len(original))
                source.write_bytes(original)
                with self.assertRaisesRegex(RuntimeError, "changed after binding"):
                    inputs.verify_coherent()

            source.write_bytes(b"trusted bytes\n")
            with BoundInputs.open(
                {"source": source}, policies=_policies({"source": source})
            ) as inputs:
                replacement = root / "replacement"
                replacement.write_bytes(source.read_bytes())
                replacement.replace(source)
                with self.assertRaisesRegex(RuntimeError, "path identity"):
                    inputs.verify_coherent()

    def test_runtime_binding_allows_only_unrelated_sibling_churn(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            source = root / "config.json"
            source.write_bytes(b'{"trusted":true}\n')

            with container_runtime.WatchedRuntimeBindings.open(
                {"config": source}
            ) as inputs:
                transient = root / "podman-exec-runtime"
                transient.write_bytes(b"runtime-only\n")
                transient.unlink()
                self.assertEqual(
                    inputs.verify_coherent()["config"],
                    hashlib.sha256(source.read_bytes()).hexdigest(),
                )

                moved = root / "config.saved"
                source.rename(moved)
                moved.rename(source)
                with self.assertRaisesRegex(
                    RuntimeError, "runtime input name changed: config"
                ):
                    inputs.verify_coherent()

    def test_runtime_binding_rejects_churn_of_every_initial_sibling_name(self) -> None:
        def mutate_bytes(path: Path, _moved: Path, original: bytes) -> None:
            path.write_bytes(b"X" * len(original))
            path.write_bytes(original)

        def mutate_metadata(path: Path, _moved: Path, _original: bytes) -> None:
            path.chmod(0o600)
            path.chmod(0o644)

        def replace_and_restore(path: Path, moved: Path, original: bytes) -> None:
            path.rename(moved)
            path.write_bytes(original)
            path.unlink()
            moved.rename(path)

        mutations = {
            "bytes": mutate_bytes,
            "metadata": mutate_metadata,
            "replacement": replace_and_restore,
        }
        for mutation, mutate in mutations.items():
            with (
                self.subTest(mutation=mutation),
                tempfile.TemporaryDirectory() as directory_name,
            ):
                root = Path(directory_name)
                source = root / "config.json"
                sibling = root / "runtime-state"
                source.write_bytes(b'{"trusted":true}\n')
                sibling.write_bytes(b"initial runtime state\n")
                sibling.chmod(0o644)
                original = sibling.read_bytes()
                with container_runtime.WatchedRuntimeBindings.open(
                    {"config": source}
                ) as inputs:
                    mutate(sibling, root / "runtime-state.saved", original)
                    with self.assertRaisesRegex(
                        RuntimeError, "runtime input baseline name changed"
                    ):
                        inputs.verify_coherent()

