    def test_runtime_binding_rejects_persistent_sibling_and_setup_race(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            source = root / "config.json"
            source.write_bytes(b"trusted\n")
            with container_runtime.WatchedRuntimeBindings.open(
                {"config": source}
            ) as inputs:
                (root / "unexpected").write_bytes(b"persistent\n")
                with self.assertRaisesRegex(
                    RuntimeError, "runtime input parent (metadata|listing) changed"
                ):
                    inputs.verify_coherent()

        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            source = root / "config.json"
            moved = root / "saved"
            source.write_bytes(b"trusted\n")
            real_open = os.open
            raced = False

            def inotify_descriptors() -> list[str]:
                result: list[str] = []
                for entry in Path("/proc/self/fd").iterdir():
                    try:
                        target = os.readlink(entry)
                    except FileNotFoundError:
                        continue
                    if target == "anon_inode:inotify":
                        result.append(entry.name)
                return result

            initial_inotify = inotify_descriptors()

            def race_open(path: object, flags: int, *args: object, **kwargs: object) -> int:
                nonlocal raced
                if path == "config.json" and kwargs.get("dir_fd") is not None and not raced:
                    raced = True
                    source.rename(moved)
                    moved.rename(source)
                return real_open(path, flags, *args, **kwargs)

            with (
                mock.patch.object(container_runtime.os, "open", side_effect=race_open),
                self.assertRaisesRegex(RuntimeError, "runtime input name changed"),
            ):
                container_runtime.WatchedRuntimeBindings.open({"config": source})
            self.assertTrue(raced)
            self.assertEqual(inotify_descriptors(), initial_inotify)
            self.assertEqual(self._fds_targeting(source), [])
            self.assertEqual(self._fds_targeting(root), [])

