            with container_runtime.WatchedRuntimeBindings.open(
                {"config": first, "containerenv": second}
            ) as inputs:
                self.assertEqual(len(inputs._parents_by_watch), 1)
                self.assertEqual(inputs.read("config"), b"{}\n")
