    def test_reserved_pid_start_transfer_failure_drains_new_descriptor(self) -> None:
        """A named-stat failure after opening a newly-created PID must release it."""
        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            config = root / "config.json"
            containerenv = root / ".containerenv"
            config.write_bytes(b"{}\n")
            containerenv.write_bytes(b"")
            with container_runtime.WatchedRuntimeBindings.open(
                {"config": config, "containerenv": containerenv},
                reserved_lifecycle=("containerenv", "conmon.pid"),
            ) as inputs:
                inputs.begin_start_transition()
                conmon = root / "conmon.pid"
                conmon.write_bytes(b"123\n")
                watch = inputs._records["containerenv"].parent.watch_number
                events = self._inotify_chunk(
                    watch, [(0x100, b"conmon.pid", 0), (0x8, b"conmon.pid", 0)]
                )
                before = set(os.listdir("/proc/self/fd"))
                real_stat = os.stat

                def failing_stat(path: object, *args: object, **kwargs: object) -> os.stat_result:
                    if path == "conmon.pid" and kwargs.get("dir_fd") == inputs._records["containerenv"].parent.descriptor:
                        raise OSError(errno.EIO, "injected named stat")
                    return real_stat(path, *args, **kwargs)

                with (
                    mock.patch.object(container_runtime, "_read_inotify_chunks", side_effect=((events,),)),
                    mock.patch.object(container_runtime.os, "stat", side_effect=failing_stat),
                    self.assertRaises(OSError),
                ):
                    inputs.complete_start_transition()
                self.assertEqual(set(os.listdir("/proc/self/fd")), before)

    def test_reserved_pid_close_failure_still_drains_every_other_owner(self) -> None:
        """Closing the PID FD may fail only after all other owners were attempted."""
        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            config = root / "config.json"
            conmon = root / "conmon.pid"
            config.write_bytes(b"{}\n")
            conmon.write_bytes(b"123\n")
            before = set(os.listdir("/proc/self/fd"))
            inputs = container_runtime.WatchedRuntimeBindings.open(
                {"config": config}, reserved_lifecycle=("config", "conmon.pid")
            )
            reserved = inputs._reserved_lifecycle["descriptor"]
            real_close = os.close
            primary = OSError(errno.EIO, "injected reserved close")

            def closing(descriptor: int) -> None:
                real_close(descriptor)
                if descriptor == reserved:
                    raise primary

            with (
                mock.patch.object(container_runtime.os, "close", side_effect=closing),
                self.assertRaises(OSError) as caught,
            ):
                inputs.close()
            self.assertIs(caught.exception, primary)
            self.assertEqual(set(os.listdir("/proc/self/fd")), before)
            inputs.close()
            self.assertEqual(set(os.listdir("/proc/self/fd")), before)

    def test_reserved_pid_start_publication_interrupt_never_closes_reused_fd(self) -> None:
        """Publishing the descriptor then faulting must clear map custody first."""
        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            config, containerenv = root / "config.json", root / ".containerenv"
            config.write_bytes(b"{}\n")
            containerenv.write_bytes(b"")
            before = set(os.listdir("/proc/self/fd"))
            inputs = container_runtime.WatchedRuntimeBindings.open(
                {"config": config, "containerenv": containerenv},
                reserved_lifecycle=("containerenv", "conmon.pid"),
            )
            primary = MemoryError("injected descriptor publication")

            class InterruptingMap(dict):
                armed = True
                def __setitem__(self, key: object, value: object) -> None:
                    super().__setitem__(key, value)
                    if key == "descriptor" and self.armed:
                        self.armed = False
                        raise primary

            inputs._reserved_lifecycle = InterruptingMap(inputs._reserved_lifecycle)
            try:
                inputs.begin_start_transition()
                (root / "conmon.pid").write_bytes(b"123\n")
                watch = inputs._records["containerenv"].parent.watch_number
                events = self._inotify_chunk(watch, [(0x100, b"conmon.pid", 0), (0x8, b"conmon.pid", 0)])
                with (
                    mock.patch.object(container_runtime, "_read_inotify_chunks", side_effect=((events,),)),
                    self.assertRaises(MemoryError) as caught,
                ):
                    inputs.complete_start_transition()
                self.assertIs(caught.exception, primary)
                reused = os.open("/dev/null", os.O_RDONLY | os.O_CLOEXEC)
                try:
                    inputs.close()
                    os.fstat(reused)
                finally:
                    try:
                        os.close(reused)
                    except OSError as error:
                        if error.errno != errno.EBADF:
                            raise
            finally:
                inputs.close()
            self.assertEqual(set(os.listdir("/proc/self/fd")), before)

