    def test_reserved_pid_native_publication_interrupt_never_closes_reused_fd(self) -> None:
        """The native-map publication/sentinel bytecode boundary owns one FD."""
        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            config_root, runtime_root = root / "config", root / "runtime"
            config_root.mkdir()
            runtime_root.mkdir()
            config = config_root / "config.json"
            containerenv = runtime_root / ".containerenv"
            config.write_bytes(b"{}\n")
            containerenv.write_bytes(b"")
            before = set(os.listdir("/proc/self/fd"))
            inputs = container_runtime.WatchedRuntimeBindings.open(
                {"config": config, "containerenv": containerenv},
                reserved_lifecycle=("containerenv", "conmon.pid"),
            )
            primary = MemoryError("injected post-publication sentinel boundary")
            function = container_runtime.WatchedRuntimeBindings._complete_start_transition
            lines, start = inspect.getsourcelines(function)
            selected = {
                start + index for index, line in enumerate(lines)
                if line.strip() == "descriptor = -1"
            }
            offsets = {
                item.offset for item in dis.get_instructions(function)
                if item.positions.lineno in selected
            }
            self.assertTrue(offsets)
            published_fd: list[int] = []

            def trace(frame: object, event: str, _argument: object):
                if getattr(frame, "f_code", None) is function.__code__:
                    frame.f_trace_opcodes = True
                    if event == "opcode" and frame.f_lasti in offsets:
                        value = inputs._reserved_lifecycle["descriptor"]
                        if isinstance(value, int):
                            published_fd.append(value)
                        raise primary
                return trace

            try:
                inputs.begin_start_transition()
                (runtime_root / "conmon.pid").write_bytes(b"123\n")
                try:
                    sys.settrace(trace)
                    with self.assertRaises(MemoryError) as caught:
                        inputs.complete_start_transition()
                finally:
                    sys.settrace(None)
                self.assertIs(caught.exception, primary)
                self.assertEqual(len(published_fd), 1)
                self.assertIsNone(inputs._reserved_lifecycle["descriptor"])
                reused = os.open("/dev/null", os.O_RDONLY | os.O_CLOEXEC)
                try:
                    self.assertEqual(reused, published_fd[0])
                    inputs.close()
                    os.fstat(reused)
                finally:
                    try:
                        os.close(reused)
                    except OSError as error:
                        if error.errno != errno.EBADF:
                            raise
            finally:
                inputs.close()
            self.assertEqual(set(os.listdir("/proc/self/fd")), before)

