    def test_runtime_stop_projection_rejects_wrong_or_unrelated_events(self) -> None:
        cases = ("wrong-mask", "added", "unrelated-delete", "remove-recreate", "target")
        for case in cases:
            with self.subTest(case=case), tempfile.TemporaryDirectory() as directory_name:
                root = Path(directory_name)
                config = self._create_podman_runtime_bundle(root)
                with container_runtime.WatchedRuntimeBindings.open(
                    {"config": config}, stop_projection_label="config"
                ) as inputs:
                    inputs.begin_stop_transition("config")
                    if case == "wrong-mask":
                        watch = next(iter(inputs._parents_by_watch))
                        name = b"attach\0"
                        padding = name + b"\0" * ((-len(name)) % 4)
                        raw = struct.pack(
                            "iIII", watch, 0x00000002, 0, len(padding)
                        ) + padding
                        with (
                            mock.patch.object(
                                container_runtime,
                                "_read_inotify_chunks",
                                return_value=(raw,),
                            ),
                            self.assertRaisesRegex(
                                RuntimeError, "stop endpoint deletion events"
                            ),
                        ):
                            inputs.complete_stop_transition("config")
                        continue
                    if case == "added":
                        (root / "extra").write_bytes(b"unexpected\n")
                    elif case == "unrelated-delete":
                        (root / "artifacts").rmdir()
                    elif case == "remove-recreate":
                        (root / "attach").unlink()
                        os.mknod(root / "attach", stat.S_IFSOCK | 0o700)
                    elif case == "target":
                        original = config.read_bytes()
                        config.write_bytes(b"X" * len(original))
                        config.write_bytes(original)
                    with self.assertRaisesRegex(
                        RuntimeError,
                        "stop (transition|endpoint)|runtime input name changed|changed after binding",
                    ):
                        inputs.complete_stop_transition("config")

    def test_runtime_stop_projection_rejects_partial_order_violations(self) -> None:
        base = [
            (0x200, b"attach", 0),
            (0x8, b"ctl", 0),
            (0x200, b"ctl", 0),
            (0x8, b"winsz", 0),
            (0x200, b"winsz", 0),
        ]
        cases = {
            "reversed": [base[0], base[2], base[1], *base[3:]],
            "duplicate": [*base, base[0]],
            "close-only": [item for item in base if item != (0x200, b"ctl", 0)],
            "delete-only": [item for item in base if item != (0x8, b"ctl", 0)],
            "extra-bit": [
                (mask | 0x4, name, cookie) if name == b"ctl" and mask == 0x8 else (mask, name, cookie)
                for mask, name, cookie in base
            ],
            "wrong-isdir-bit": [
                (mask | 0x40000000, name, cookie)
                if name == b"attach"
                else (mask, name, cookie)
                for mask, name, cookie in base
            ],
            "extra-name": [*base, (0x200, b"other", 0)],
            "nonzero-cookie": [
                (mask, name, 7) if name == b"attach" else (mask, name, cookie)
                for mask, name, cookie in base
            ],
            "target": [*base, (0x4, b"config.json", 0)],
        }
        for case, events in cases.items():
            with self.subTest(case=case), tempfile.TemporaryDirectory() as directory_name:
                root = Path(directory_name)
                config = self._create_podman_runtime_bundle(root)
                with container_runtime.WatchedRuntimeBindings.open(
                    {"config": config}, stop_projection_label="config"
                ) as inputs:
                    inputs.begin_stop_transition("config")
                    for name in ("attach", "ctl", "winsz"):
                        (root / name).unlink()
                    watch = next(iter(inputs._parents_by_watch))
                    raw = self._inotify_chunk(watch, events)
                    with (
                        mock.patch.object(
                            container_runtime,
                            "_read_inotify_chunks",
                            return_value=(raw,),
                        ),
                        self.assertRaisesRegex(
                            RuntimeError,
                            "stop endpoint deletion events|runtime input name changed",
                        ),
                    ):
                        inputs.complete_stop_transition("config")

