    def test_a2r1_incremental_reader_stops_at_event_bound(self) -> None:
        """Catch eager inotify accumulation before the 1,024-event limit."""
        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            source = root / "config.json"
            source.write_bytes(b"{}\n")
            with container_runtime.WatchedRuntimeBindings.open({"config": source}) as inputs:
                watch = inputs._records["config"].parent.watch_number
                chunk = self._inotify_chunk(watch, [(0x2, b"transient", 0)] * 128)
                calls: list[int] = []
                primary = OSError(errno.EIO, "reader ran past bounded acquisition")

                def reading(descriptor: int, size: int) -> bytes:
                    self.assertEqual(descriptor, inputs._watch_descriptor)
                    calls.append(size)
                    if len(calls) > 9:
                        raise primary
                    return chunk

                with (
                    mock.patch.object(container_runtime.os, "read", side_effect=reading),
                    self.assertRaisesRegex(RuntimeError, "event count limit"),
                ):
                    inputs._collect_events()
                self.assertEqual(calls, calls[:9])
                self.assertEqual(len(calls), 9)
                self.assertTrue(all(size <= 4096 for size in calls))

