    def test_a2r1r1_native_collection_validation_interrupt_is_terminal(self) -> None:
        """Catch KeyboardInterrupt between collection and start validation."""
        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            config, containerenv, conmon = root / "config.json", root / ".containerenv", root / "conmon.pid"
            config.write_bytes(b"{}\n")
            containerenv.write_bytes(b"")
            baseline = set(os.listdir("/proc/self/fd"))
            inputs = container_runtime.WatchedRuntimeBindings.open(
                {"config": config, "containerenv": containerenv},
                reserved_lifecycle=("containerenv", "conmon.pid"),
            )
            primary = KeyboardInterrupt("injected collection-validation boundary")
            function = container_runtime.WatchedRuntimeBindings._complete_start_transition
            lines, start = inspect.getsourcelines(function)
            target_lines = {start + index for index, line in enumerate(lines) if line.strip() == 'initially_present = reserved["initial_present"]'}
            offsets = {item.offset for item in dis.get_instructions(function) if item.positions.lineno in target_lines}
            self.assertTrue(offsets)
            def trace(frame: object, event: str, _argument: object):
                if getattr(frame, "f_code", None) is function.__code__:
                    frame.f_trace_opcodes = True
                    if event == "opcode" and frame.f_lasti in offsets:
                        raise primary
                return trace
            try:
                inputs.begin_start_transition()
                conmon.write_bytes(b"123\n")
                try:
                    sys.settrace(trace)
                    with self.assertRaises(KeyboardInterrupt) as caught:
                        inputs.complete_start_transition()
                finally:
                    sys.settrace(None)
                self.assertIs(caught.exception, primary)
                self.assertTrue(inputs._reserved_lifecycle["failed"])
                self.assertEqual(inputs._reserved_lifecycle["start_state"], "failed")
                with self.assertRaisesRegex(RuntimeError, "terminally failed"):
                    inputs.begin_start_transition()
            finally:
                inputs.close()
                inputs.close()
            self.assertEqual(set(os.listdir("/proc/self/fd")), baseline)

