    def test_private_key_descriptor_rejects_hardlinks_and_foreign_owner(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            key = Path(directory_name) / "module-signing.key"
            alias = key.with_name("alias.key")
            key.write_bytes(b"test-only private bytes")
            key.chmod(0o600)
            alias.hardlink_to(key)
            descriptor = os.open(key, os.O_RDONLY | os.O_CLOEXEC)
            try:
                with self.assertRaisesRegex(ValueError, "private key descriptor"):
                    kernel_build._validate_private_key_descriptor(descriptor)
            finally:
                os.close(descriptor)
            alias.unlink()

            descriptor = os.open(key, os.O_RDONLY | os.O_CLOEXEC)
            real_fstat = os.fstat

            def foreign_owner(value: int) -> os.stat_result:
                status = real_fstat(value)
                fields = list(status)
                fields[4] = os.geteuid() + 1
                return os.stat_result(fields)

            try:
                with (
                    mock.patch.object(
                        kernel_build.os, "fstat", side_effect=foreign_owner
                    ),
                    self.assertRaisesRegex(ValueError, "private key descriptor"),
                ):
                    kernel_build._validate_private_key_descriptor(descriptor)
            finally:
                os.close(descriptor)

