            duplicates = []
            def probe(expected: object) -> None:
                if not duplicates:
                    duplicates.append(os.dup(outputs.descriptor("result")))
                else:
                    proof_io._assert_artifact_writer_custody(expected, ())
            try:
                with self.assertRaisesRegex(RuntimeError, "writer custody remains"):
                    outputs.reopen_read_only(process_probe=probe)
            finally:
                for descriptor in duplicates:
                    os.close(descriptor)
                outputs.close()

