    def test_fixed_descriptor_partial_setup_preserves_every_original_and_flag(self) -> None:
        for stage, fail_at in [("save-or-copy", index) for index in range(1, 5)] + [("install", index) for index in range(1, 3)]:
            with self.subTest(stage=stage, fail_at=fail_at):
                left, right, source = [os.memfd_create(label, os.MFD_CLOEXEC) for label in ("original-left", "original-right", "source")]
                for descriptor, data in ((left, b"left"), (right, b"right"), (source, b"source")):
                    os.write(descriptor, data)
                os.set_inheritable(left, True)
                initial_count = len(os.listdir("/proc/self/fd"))
                real_fcntl, real_dup2 = fcntl.fcntl, os.dup2
                calls = 0
                def fail_fcntl(descriptor: int, operation: int, argument: int = 0) -> int:
                    nonlocal calls
                    if operation == fcntl.F_DUPFD_CLOEXEC:
                        calls += 1
                        if calls == fail_at:
                            raise OSError(errno.EMFILE, "injected descriptor allocation failure")
                    return real_fcntl(descriptor, operation, argument)
                def fail_dup2(source_fd: int, target: int, *, inheritable: bool = True) -> int:
                    nonlocal calls
                    calls += 1
                    if calls == fail_at:
                        raise OSError(errno.EMFILE, "injected descriptor installation failure")
                    return real_dup2(source_fd, target, inheritable=inheritable)
                try:
                    with mock.patch.object(proof_io.fcntl, "fcntl", side_effect=fail_fcntl if stage == "save-or-copy" else real_fcntl), mock.patch.object(proof_io.os, "dup2", side_effect=fail_dup2 if stage == "install" else real_dup2):
                        with self.assertRaises(OSError):
                            with FixedDescriptors({left: source, right: source}):
                                self.fail("injected setup failure did not run")
                    self.assertEqual(os.pread(left, 16, 0), b"left")
                    self.assertEqual(os.pread(right, 16, 0), b"right")
                    self.assertEqual(os.pread(source, 16, 0), b"source")
                    self.assertTrue(os.get_inheritable(left))
                    self.assertFalse(os.get_inheritable(right))
                    self.assertEqual(len(os.listdir("/proc/self/fd")), initial_count)
                finally:
                    for descriptor in (left, right, source):
                        try:
                            os.close(descriptor)
                        except OSError as error:
                            if error.errno != errno.EBADF:
                                raise

