    def test_container_removal_never_executes_against_a_replaced_store(self) -> None:
        baseline = set(os.listdir("/proc/self/fd"))
        with tempfile.TemporaryDirectory() as name:
            root = Path(name)
            policy = container_runtime.SealedPodmanPolicy.create()
            store = PodmanStore(root / "store", environment={}, policy=policy)
            store.initialize()
            scratch = root / "scratch"
            scratch.mkdir(mode=0o700)
            backend = container_runtime.PodmanContainerBackend(store=store, image="sha256:" + "a" * 64, container="test-container", scratch=scratch, capsule_descriptor=99, archive_descriptor=98, archive_sha256="b" * 64, manifest_digest="sha256:" + "c" * 64, execution_arguments={})
            backend._created = True
            store.base.rename(root / "original-store")
            store.base.mkdir()
            marker = store.base / "unrelated-container"
            marker.write_bytes(b"must remain untouched")
            def unsafe_pathname_remove(*arguments: object, **kwargs: object) -> subprocess.CompletedProcess[bytes]:
                marker.unlink()
                return subprocess.CompletedProcess([], 0, stdout=b"")
            try:
                with mock.patch.object(store, "run", side_effect=unsafe_pathname_remove):
                    with self.assertRaisesRegex(RuntimeError, "cleanup"):
                        backend.remove()
                self.assertTrue(marker.exists())
                self.assertEqual(marker.read_bytes(), b"must remain untouched")
            finally:
                try:
                    backend.close()
                finally:
                    try:
                        store.close_scope()
                    finally:
                        policy.close()
        self.assertEqual(set(os.listdir("/proc/self/fd")), baseline)

