    def test_fixed_descriptors_handle_full_sparse_cyclic_and_alias_maps(self) -> None:
        left = proof_io.seal_public_bytes(b"left", "left")
        right = proof_io.seal_public_bytes(b"right", "right")
        try:
            for mapping in (
                {left.fd: left.fd},
                {left.fd: right.fd, right.fd: left.fd},
                {fd: left.fd if fd % 2 else right.fd for fd in (*range(20, 27), *range(30, 34))},
                {20: left.fd, 41: right.fd, 80: left.fd},
            ):
                before = set(os.listdir("/proc/self/fd"))
                expected = {target: os.pread(source, 10, 0) for target, source in mapping.items()}
                with FixedDescriptors(mapping):
                    for target, data in expected.items():
                        self.assertEqual(os.pread(target, 10, 0), data)
                        self.assertTrue(os.get_inheritable(target))
                self.assertEqual(set(os.listdir("/proc/self/fd")), before)
                self.assertEqual(os.pread(left.fd, 10, 0), b"left")
                self.assertEqual(os.pread(right.fd, 10, 0), b"right")
        finally:
            left.close()
            right.close()

