    def test_live_pid1_contract_rejects_extra_process_fd_mount_or_network(self) -> None:
        base = _live_fixture()
        validate_live_process_record(base)
        malformed_owner = copy.deepcopy(base)
        malformed_owner["exe"]["uid"] = 2**32 - 2
        malformed_owner["mapped_files"]["/usr/bin/sleep"]["uid"] = 2**32 - 2
        with self.assertRaisesRegex(RuntimeError, "executable.*ID"):
            validate_live_process_record(malformed_owner)
        mutations = {
            "process": lambda value: value["top"].append(
                {"host_pid": 1235, "pid": 2, "comm": "evil"}
            ),
            "fd": lambda value: value["fds"].update({"9": "/secret"}),
            "mount": lambda value: value.update({"mount_contract": "unexpected"}),
            "network": lambda value: value["network"]["listeners"].append("tcp:22"),
            "executable": lambda value: value["exe"].update({"sha256": "z" * 64}),
            "pid": lambda value: value["pid_identity"].update(
                {"starttime_ticks": 0}
            ),
        }
        for label, mutate in mutations.items():
            value = json.loads(json.dumps(base))
            mutate(value)
            with self.subTest(label=label):
                with self.assertRaisesRegex(RuntimeError, label):
                    validate_live_process_record(value)

    def test_live_mount_evidence_rejects_rehashed_topology_corruption(self) -> None:
        mutations = {
            "extra-field": lambda rows: rows[0].update({"extra": 1}),
            "parent": lambda rows: next(row for row in rows if row["key"] == "/dev/pts").update({"parent": "/"}),
            "device-class": lambda rows: next(row for row in rows if row["key"] == "/tmp/work").update({"device_class": "proc"}),
            "mask-mode": lambda rows: next(row for row in rows if row["key"] == "/proc/keys").update({"options": ["rw", "nosuid"]}),
            "stack-edge": lambda rows: next(row for row in rows if row["key"].endswith("powercap#2")).update({"parent": "/sys"}),
        }
        for label, mutate in mutations.items():
            value = _live_fixture()
            mutate(value["mount_graph"]["records"])
            value["mount_graph"]["semantic_sha256"] = _object_sha256(value["mount_graph"]["records"])
