    def test_live_maps_parser_rejects_deleted_rwx_and_unknown_executable_maps(self) -> None:
        good = (
            b"00400000-00401000 r-xp 00000000 08:01 101 /usr/bin/sleep\n"
            b"7fff0000-7fff1000 r-xp 00000000 00:00 0 [vdso]\n"
        )
        parsed, anonymous = container_runtime._parse_executable_maps(good)
        self.assertEqual(parsed[0]["path"], "/usr/bin/sleep")
        self.assertEqual(anonymous[0]["name"], "[vdso]")
        bad_values = {
            "deleted": good.replace(b"/usr/bin/sleep", b"/usr/bin/sleep (deleted)"),
            "writable executable": good.replace(b"r-xp", b"rwxp", 1),
            "anonymous executable": good.replace(b"[vdso]", b"[evil]"),
            "missing pathname": good.replace(b" /usr/bin/sleep", b"", 1),
        }
        for label, value in bad_values.items():
            with self.subTest(label=label):
                with self.assertRaisesRegex(RuntimeError, label):
                    container_runtime._parse_executable_maps(value)

    def test_process_starttime_parser_binds_exact_pid_and_positive_clock(self) -> None:
        fields = [b"S"] + [b"0"] * 18 + [b"123456"] + [b"0"] * 8
        value = b"4321 (sleep) " + b" ".join(fields) + b"\n"
        self.assertEqual(container_runtime._process_starttime(value, 4321), 123456)
