    def test_scratch_binding_rejects_ancestor_replacement(self) -> None:
        with tempfile.TemporaryDirectory() as name:
            root = Path(name)
            parent = root / "parent"
            parent.mkdir()
            scratch = parent / "scratch"
            scratch.mkdir(mode=0o700)
