    def test_production_spec_audit_rejects_escaped_or_former_runroot_paths(self) -> None:
        baseline_descriptors = set(os.listdir("/proc/self/fd"))
        for attacked in (None, "OCIConfigPath", "OCIConfigPath-former-runroot", "StaticDir", "ConmonPidFile", "rootfs"):
            with self.subTest(path=attacked), tempfile.TemporaryDirectory() as name:
                root = Path(name)
                policy = container_runtime.SealedPodmanPolicy.create()
                store = PodmanStore(root / "store", environment={}, policy=policy)
                store.initialize()
                spec, scratch, static, runtime, rootfs = self._real_pinned_spec(root / "outside")
                scratch.chmod(0o700)
                container_id = "d" * 64
                targets = {
                    "OCIConfigPath": store.graphroot / "vfs-containers" / container_id / "userdata/config.json",
                    "StaticDir": store.graphroot / "vfs-containers" / container_id / "userdata",
                    "ConmonPidFile": store.runroot / "vfs-containers" / container_id / "userdata/conmon.pid",
                    "rootfs": store.graphroot / "vfs/dir" / ("e" * 64),
                }
                for target in targets.values():
                    target.parent.mkdir(parents=True, exist_ok=True)
                targets["StaticDir"].mkdir(exist_ok=True)
                targets["rootfs"].mkdir()
                replacements = {
                    "OCIConfigPath": runtime / "config.json",
                    "StaticDir": static,
                    "ConmonPidFile": runtime / "conmon.pid",
                    "rootfs": rootfs,
                }
                if attacked == "OCIConfigPath-former-runroot":
                    targets["OCIConfigPath"] = store.runroot / "vfs-containers" / container_id / "userdata/config.json"
                elif attacked is not None:
                    targets[attacked] = replacements[attacked]
                runtime = targets["ConmonPidFile"].parent
                (runtime / ".containerenv").write_bytes(b"")
                targets["ConmonPidFile"].write_bytes(b"123\n")
                spec["root"]["path"] = str(targets["rootfs"])
                for mount in spec["mounts"]:
                    if mount["destination"] == "/dev/shm":
                        mount["source"] = str(targets["StaticDir"] / "shm")
                    if mount["destination"] == "/run/.containerenv":
                        mount["source"] = str(runtime / ".containerenv")
                targets["OCIConfigPath"].write_text(json.dumps(spec))
                record = {key: str(value) for key, value in targets.items() if key != "rootfs"}
                record["Name"] = "containment-test"
                record["Id"] = container_id
                backend = container_runtime.PodmanContainerBackend(
                    store=store, image="sha256:" + "a" * 64,
                    container="containment-test", scratch=scratch,
                    capsule_descriptor=10, archive_descriptor=11,
                    archive_sha256="b" * 64, manifest_digest="sha256:" + "c" * 64,
                    execution_arguments={},
                )
                backend._state = container_runtime.LifecycleState.CREATED_INIT
                backend.container_id = container_id
                watched_open = container_runtime.WatchedRuntimeBindings.open
                try:
                    with (
                        mock.patch.object(container_runtime, "_podman_inspect_record", return_value=record),
                        mock.patch.object(container_runtime.WatchedRuntimeBindings, "open", side_effect=lambda paths, **kwargs: watched_open(paths)),
                    ):
                        if attacked is None:
                            backend.audit_effective_spec()
                            self.assertEqual(set(store._reported_paths), {
                                "OCIConfigPath", "StaticDir", "ConmonPidFile", "rootfs"
                            })
                        else:
                            with self.assertRaisesRegex(RuntimeError, "escapes.*store|retained container ID"):
                                backend.audit_effective_spec()
                finally:
                    proof_io._release_preserving_primary(
                        (backend.remove, backend.close, store.close_scope, policy.close),
                        sys.exception(),
                    )
        self.assertEqual(set(os.listdir("/proc/self/fd")), baseline_descriptors)

    @staticmethod
    def _real_pinned_spec(root: Path) -> tuple[dict[str, object], Path, Path, Path, Path]:
        scratch = root / "scratch"
        static = root / "static/userdata"
        runtime = root / "runtime/userdata"
        rootfs = root / "rootfs"
        for directory in (scratch, static, runtime, rootfs):
            directory.mkdir(parents=True)
        (static / "shm").mkdir()
        (runtime / ".containerenv").write_bytes(b"")
        fixture = REPO / "tests/gate01/fixtures/oci-config-podman-5.7-crun-1.21.json"
        value = json.loads(fixture.read_text(encoding="utf-8"))
        value["root"]["path"] = str(rootfs)
        value["hostname"] = os.uname().nodename
        replacements = {
            "/tmp/work": str(scratch),
            "/dev/shm": str(static / "shm"),
            "/run/.containerenv": str(runtime / ".containerenv"),
        }
        for mount in value["mounts"]:
            if mount["destination"] in replacements:
                mount["source"] = replacements[mount["destination"]]
        return value, scratch, static, runtime, rootfs

    def test_generated_oci_spec_has_exact_no_hook_mount_and_environment_contract(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            spec, scratch, static, runtime, rootfs = self._real_pinned_spec(root)
            validate_effective_oci_spec(
                spec,
                scratch=scratch,
                scratch_identity=(scratch.stat().st_dev, scratch.stat().st_ino),
                rootfs_path=rootfs,
                static_directory=static,
                runtime_directory=runtime,
            )
            for label, mutate in (
                ("hooks", lambda value: value.update({"hooks": None})),
                ("hooks", lambda value: value.update({"hooks": {}})),
                ("root", lambda value: value["root"].update({"readonly": False})),
                ("mount", lambda value: value["mounts"].append({"destination": "/repo"})),
                ("environment", lambda value: value["process"]["env"].append("HOST=x")),
                ("masked-path", lambda value: value["linux"]["maskedPaths"].pop()),
                ("ordered environment", lambda value: value["process"]["env"].reverse()),
                ("ordered mount", lambda value: value["mounts"].reverse()),
                ("namespace", lambda value: value["linux"]["namespaces"][1].update({"path": "/proc/1/ns/net"})),
                ("capabilities", lambda value: value["process"].update({"capabilities": {"bounding": []}})),
                ("process field", lambda value: value["process"].update({"apparmorProfile": "host"})),
                ("linux field", lambda value: value["linux"].update({"rootfsPropagation": "shared"})),
                ("root field", lambda value: value["root"].update({"unexpected": True})),
            ):
                changed = json.loads(json.dumps(spec))
                mutate(changed)
                with self.subTest(label=label):
                    with self.assertRaisesRegex(ValueError, label):
                        validate_effective_oci_spec(
                            changed,
                            scratch=scratch,
                            scratch_identity=(scratch.stat().st_dev, scratch.stat().st_ino),
                            rootfs_path=rootfs,
                            static_directory=static,
                            runtime_directory=runtime,
                        )

    def test_strict_pinned_contract_rejects_wrong_and_symlinked_scratch(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            spec, scratch, static, runtime, rootfs = self._real_pinned_spec(Path(directory))
            identity = (scratch.stat().st_dev, scratch.stat().st_ino)
            kwargs = dict(scratch=scratch, scratch_identity=identity, rootfs_path=rootfs, static_directory=static, runtime_directory=runtime)
            changed = copy.deepcopy(spec)
            next(mount for mount in changed["mounts"] if mount["destination"] == "/tmp/work")["source"] = str(Path(directory) / "wrong")
            with self.assertRaises(ValueError): validate_effective_oci_spec(changed, **kwargs)
            scratch.rename(Path(directory) / "moved")
            scratch.symlink_to("moved", target_is_directory=True)
            with self.assertRaises(ValueError): validate_effective_oci_spec(spec, **kwargs)

