            report = candidate / "build-report.json"
            real_loads = json.loads
            attacked = False
            def loads(value, *args, **kwargs):
                nonlocal attacked
                result = real_loads(value, *args, **kwargs)
                if not attacked and isinstance(result, dict) and "acceptance" in result:
                    attacked = True
                    report.write_bytes(b'{"acceptance":"not-pending"}\n')
                return result
