            with mock.patch.object(proof_io.os, "geteuid", return_value=0), mock.patch.object(proof_io.os, "getegid", return_value=0):
                records = proof_io._tree_manifest(candidate, allowed, expected_uid=owner_uid, expected_gid=owner_gid)
            self.assertTrue(all(record["uid"] == owner_uid and record["gid"] == owner_gid for record in records))
