    def test_candidate_and_bound_tree_reject_xattrs_anywhere(self) -> None:
        with tempfile.TemporaryDirectory() as name:
            root = Path(name)
            candidate, allowed = self._candidate(root)
            final, receipt = root / "kernel", root / "kernel.receipt.json"
            for relative in (".", "rpmbuild", "build.log"):
                with self.subTest(phase="candidate", relative=relative):
                    target = candidate / relative
                    os.setxattr(target, "user.uncommitted", b"not represented in receipt")
                    try:
                        with self.assertRaisesRegex(ReceiptError, "xattr"):
                            create_detached_receipt(candidate, intended_path=final, allowed_files=allowed, source_capsule_sha256="a" * 64, rpm_manifest_sha256="b" * 64, expected_uid=os.geteuid(), expected_gid=os.getegid())
                    finally:
                        os.removexattr(target, "user.uncommitted")
            value = create_detached_receipt(candidate, intended_path=final, allowed_files=allowed, source_capsule_sha256="a" * 64, rpm_manifest_sha256="b" * 64, expected_uid=os.geteuid(), expected_gid=os.getegid())
            publish_candidate(candidate, final, receipt, value, expected_uid=os.geteuid(), expected_gid=os.getegid())
            for target in (final, final / "rpmbuild", final / "build.log", receipt):
                with self.subTest(phase="accepted", relative=target.name):
                    if target == receipt:
                        target.chmod(0o644)
                    os.setxattr(target, "user.uncommitted", b"not represented in receipt")
                    if target == receipt:
                        target.chmod(0o444)
                    try:
                        with self.assertRaisesRegex(ReceiptError, "xattr"):
                            with proof_io.BoundAcceptedTree.open(final, receipt, allowed_files=allowed, expected_uid=os.geteuid(), expected_gid=os.getegid()):
                                pass
                    finally:
                        if target == receipt:
                            target.chmod(0o644)
                        os.removexattr(target, "user.uncommitted")
                        if target == receipt:
                            target.chmod(0o444)

