    def _candidate(self, root: Path) -> tuple[Path, dict[str, str]]:
        candidate = root / "candidate"
        rpm = candidate / "rpmbuild/RPMS/x86_64/kernel-openmythos.rpm"
        srpm = candidate / "rpmbuild/SRPMS/kernel-openmythos.src.rpm"
        rpm.parent.mkdir(parents=True)
        srpm.parent.mkdir(parents=True)
        rpm.write_bytes(b"binary")
        srpm.write_bytes(b"source")
        (candidate / "rpm-artifacts.json").write_text("{}\n", encoding="utf-8")
        (candidate / "installed-files.json").write_text("{}\n", encoding="utf-8")
        (candidate / "build.log").write_text("complete\n", encoding="utf-8")
        (candidate / "build-report.json").write_text(
            json.dumps({"acceptance": "pending-detached-receipt"}) + "\n",
            encoding="utf-8",
        )
        candidate.chmod(0o755)
        for path in candidate.rglob("*"):
            path.chmod(0o755 if path.is_dir() else 0o644)
        allowed = {
            "rpmbuild/RPMS/x86_64/kernel-openmythos.rpm": "rpm",
            "rpmbuild/SRPMS/kernel-openmythos.src.rpm": "srpm",
            "rpm-artifacts.json": "manifest",
            "installed-files.json": "installed",
            "build.log": "log",
            "build-report.json": "report",
        }
        return candidate, allowed

