class EvidenceReceiptProtocolTests(unittest.TestCase):
    def test_evidence_consumers_reject_xattrs_and_numeric_aliases(self) -> None:
        for mutation in ("payload-xattr", "receipt-xattr", "schema-bool", "payload-float", "duplicate", "nan"):
            with self.subTest(mutation=mutation), tempfile.TemporaryDirectory() as name:
                root = Path(name)
                final, receipt = root / "proof.json", root / "proof.receipt.json"
                value = proof_io.publish_evidence_file(b'{"verdict":"pass"}\n', final=final, receipt=receipt, kind="comparison", input_sha256={"input": "a" * 64}, expected_uid=os.geteuid(), expected_gid=os.getegid())
                target = final if mutation == "payload-xattr" else receipt
                target.chmod(0o644)
                if mutation.endswith("xattr"):
                    os.setxattr(target, "user.uncommitted", b"not committed")
                else:
                    if mutation == "schema-bool":
                        value["schema_version"] = True
                    elif mutation == "payload-float":
                        value["payload"]["size"] = float(value["payload"]["size"])
                    encoded = proof_io._canonical_json(value)
                    if mutation == "duplicate":
                        encoded = encoded.replace(b'{\n', b'{\n  "schema_version": 1,\n', 1)
                    elif mutation == "nan":
                        encoded = encoded.replace(b'"schema_version": 1', b'"schema_version": NaN')
                    target.write_bytes(encoded)
                target.chmod(0o444)
                with self.assertRaises(ReceiptError):
                    proof_io.validate_evidence_receipt(final, receipt, kind="comparison", expected_input_sha256={"input": "a" * 64}, expected_uid=os.geteuid(), expected_gid=os.getegid())

    def test_evidence_publisher_rejects_installed_marker_metadata_before_durability(self) -> None:
        for mutation in ("mode", "xattr"):
            with self.subTest(mutation=mutation), tempfile.TemporaryDirectory() as name:
                root = Path(name)
                final, receipt = root / "proof.json", root / "proof.receipt.json"
                def publisher(parent, basename, value):
                    proof_io._publish_evidence_receipt_at(parent, basename, value)
                    receipt.chmod(0o644)
                    if mutation == "xattr":
                        os.setxattr(receipt, "user.uncommitted", b"not committed")
                        receipt.chmod(0o444)
                with self.assertRaises(ReceiptError):
                    proof_io.publish_evidence_file(b'{}\n', final=final, receipt=receipt, kind="comparison", input_sha256={"input": "a" * 64}, publish_receipt=publisher, expected_uid=os.geteuid(), expected_gid=os.getegid())
                self.assertFalse(receipt.exists())
                self.assertFalse(final.exists())

