            durable = False
            original = os.fsync
            def fsync(descriptor: int) -> None:
                nonlocal durable
                original(descriptor)
                if stat.S_ISDIR(os.fstat(descriptor).st_mode) and receipt.exists():
                    durable = True
            with mock.patch.object(proof_io.os, "fsync", side_effect=fsync):
                proof_io.publish_evidence_file(b"evidence", final=final, receipt=receipt, kind="proof", input_sha256={"input": "a" * 64}, before_receipt=lambda: self.assertFalse(durable), expected_uid=os.geteuid(), expected_gid=os.getegid())
            self.assertTrue(durable)

