            with self.assertRaisesRegex(ReceiptError, "identity"):
                proof_io.validate_evidence_receipt(
                    final,
                    receipt,
                    kind="kernel-rpm-comparison",
                    expected_input_sha256=wrong_inputs, expected_uid=os.geteuid(), expected_gid=os.getegid()
                )

            final.chmod(0o644)
            final.write_bytes(b'{"verdict":"forged"}\n')
            with self.assertRaisesRegex(ReceiptError, "payload"):
                proof_io.validate_evidence_receipt(
                    final,
                    receipt,
                    kind="kernel-rpm-comparison",
                    expected_input_sha256=inputs, expected_uid=os.geteuid(), expected_gid=os.getegid()
                )

