    def test_single_file_rollback_attempts_every_removal_after_unlink_failure(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            root = Path(directory_name)
            final = root / "comparison.json"
            receipt = root / "comparison.receipt.json"
            callback_count = 0
            unlink_calls: list[str] = []
            real_unlink = os.unlink

            def fail_final_callback() -> None:
                nonlocal callback_count
                callback_count += 1
                if callback_count == 2:
                    raise RuntimeError("injected final boundary failure")

            def fail_receipt_unlink_once(
                path: str | bytes | os.PathLike[str] | os.PathLike[bytes],
                *,
                dir_fd: int | None = None,
            ) -> None:
                name = os.fsdecode(path)
                unlink_calls.append(name)
                if name == receipt.name and unlink_calls.count(name) == 1:
                    raise OSError("injected receipt rollback failure")
                real_unlink(path, dir_fd=dir_fd)

            with (
                mock.patch.object(
                    proof_io.os, "unlink", side_effect=fail_receipt_unlink_once
                ),
                self.assertRaisesRegex(RuntimeError, "injected final boundary failure") as caught,
            ):
                proof_io.publish_evidence_file(
                    b'{"verdict":"pass"}\n',
                    final=final,
                    receipt=receipt,
                    kind="comparison",
                    input_sha256={"builder": "a" * 64},
                    before_receipt=fail_final_callback, expected_uid=os.geteuid(), expected_gid=os.getegid()
                )
            self.assertEqual(caught.exception.__notes__, ["additional evidence installed-file rollback failed"])
            self.assertIn(receipt.name, unlink_calls)
            self.assertIn(final.name, unlink_calls)
            self.assertFalse(final.exists())
            # The injected unlink failure may leave the marker, but without its
            # committed sibling it is deliberately unconsumable.
            self.assertTrue(receipt.exists())

