    def test_runtime_semantics_reject_cross_field_and_rehashed_corruptions(self) -> None:
        capsule = self._source_capsule()
        repository = Path("/synthetic-evidence")
        def check(rootfs: dict[str, object], contract: dict[str, object]) -> None:
            kernel_build._validate_runtime_evidence(rootfs, contract, capsule, repository=repository, builder="builder-a", expected_uid=os.getuid(), expected_gid=os.getgid())
        check(*_runtime_evidence(repository, "builder-a", capsule))
        for role in ("build", "inspection"):
            rootfs, contract = _runtime_evidence(repository, "builder-a", capsule)
            contract[role]["vfs_normalization"]["raw_operations"] = []
            try:
                check(rootfs, contract)
            except Exception as error:
                self.fail(f"complete empty raw operation ledger rejected: {error}")
        def graph_change(rootfs: dict[str, object], contract: dict[str, object]) -> None:
            for live in (rootfs["build"]["live"], contract["build"]["live_attestation"]):
                graph = live["host"]["mount_graph"]
                next(row for row in graph["records"] if row["key"] == "/tmp/work")["root"] = "/wrong/scratch"
                graph["semantic_sha256"] = _object_sha256(graph["records"])
        def live_change(field: str, value: object):
            return lambda rootfs, contract: [record["host"].update({field: value}) for record in (rootfs["build"]["live"], contract["build"]["live_attestation"])]
        mutations = {
            "extra-top": lambda r, c: r.update({"extra": 1}),
            "source-oci": lambda r, c: r["expected"].update({"semantic_sha256": "a" * 64}),
            "transition-order": lambda r, c: r["build"]["transitions"].reverse(),
            "live-link": lambda r, c: r["build"]["live"]["inside"].update({"nonce": "a" * 64}),
            "key-scope": lambda r, c: c["key_scope"].update({"inspection": True}),
            "policy-hash": lambda r, c: c["build"]["sealed_policy_sha256"].update({"containers_conf_sha256": "a" * 64}),
            "hooks": lambda r, c: c["build"].update({"hooks_present": True}),
            "image-null-basis": lambda r, c: c["build"]["image_identity"].update({"basis": "podman-manifest-and-held-archive"}),
            "image-empty-digest": lambda r, c: c["build"]["image_identity"].update({"podman_digest": ""}),
            "store-parent": lambda r, c: c["build"]["store_bindings"]["directories"]["store-runroot"].update({"parent_ino": 1}),
            "config-inode": lambda r, c: c["build"]["store_bindings"]["reported_paths"]["OCIConfigPath"]["target"].update({"ino": 1}),
            "container-id": lambda r, c: c["build"].update({"container_id": "A" * 64}),
            "cross-container-path": lambda r, c: c["build"]["store_bindings"]["reported_paths"]["ConmonPidFile"].update({"path": c["build"]["store_bindings"]["reported_paths"]["ConmonPidFile"]["path"].replace("a" * 64, "f" * 64)}),
            "graph-root": graph_change,
            "host-threads-bool": live_change("threads", True),
            "host-cap-bool": live_change("capabilities", {"ambient": False, "bounding": 0, "effective": 0, "inheritable": 0, "permitted": 0}),
            "multiset-bool": lambda r, c: c["build"]["runtime_input_binding"]["stop_projection"]["event_multiset"][0].update({"count": True}),
            "stop-order": lambda r, c: c["build"]["runtime_input_binding"]["stop_projection"]["observed_events"].reverse(),
            "stop-parent": lambda r, c: c["build"]["runtime_input_binding"]["stop_projection"]["post_parent_metadata"].update({"ino": 1}),
            "stop-survivor": lambda r, c: c["build"]["runtime_input_binding"]["stop_projection"]["survivor_metadata"]["shm"]["after"].update({"mode": 0o755}),
            "no-op-normalization": lambda r, c: c["build"]["vfs_normalization"]["directory_mtimes"].update({"/": {"from_mtime_ns": 0, "to_mtime_ns": 0}}),
            "regular-hardlink-repair": lambda r, c: c["build"]["vfs_normalization"]["hardlinks"].append({"field": "hardlink_group", "path": "/usr/bin/sleep", "representative": "/usr/bin/other", "before": {"dev": 1, "ino": 2, "nlink": 1}, "result": {"dev": 1, "ino": 3, "nlink": 2}}),
        }
        for label, mutate in mutations.items():
            rootfs, contract = _runtime_evidence(repository, "builder-a", capsule)
            mutate(rootfs, contract)
            with self.subTest(label=label), self.assertRaises((RuntimeError, ValueError)):
                check(rootfs, contract)
        for role in ("build", "inspection"):
            for phase in ("before", "authorized", "after"):
                for field, value in (("raw_sha256", "f" * 64), ("root_entry", {**capsule["oci_rootfs"]["root_entry"], "uid": False}), ("oci_authority", {}), ("non_root_entry_count", True)):
                    rootfs, contract = _runtime_evidence(repository, "builder-a", capsule)
                    rootfs[role][phase][field] = value
                    with self.subTest(role=role, phase=phase, field=field), self.assertRaises((RuntimeError, ValueError)):
                        check(rootfs, contract)

    def test_semantic_postfix_rejects_numeric_aliases_ownership_and_reversed_ranges(self) -> None:
        repository = Path("/synthetic-evidence")
        capsule = self._source_capsule()
        def anchor_owner(rootfs, contract):
            for phase in ("before", "authorized", "after"):
                for name in ("root", "name"):
                    rootfs["build"][phase]["root_anchor"][name]["uid"] = 777
        def top_pid(rootfs, contract):
            for live in (rootfs["build"]["live"], contract["build"]["live_attestation"]):
                live["host"]["top"][0]["pid"] = True
        def reversed_range(rootfs, contract):
            for live in (rootfs["build"]["live"], contract["build"]["live_attestation"]):
                live["host"]["mapped_files"]["/usr/bin/sleep"]["ranges"] = ["ffffffff-00000000"]
        cases = {
            "expected-bool": lambda r, c: r["expected"]["root_entry"].update({"uid": False}),
            "survivor-bool": lambda r, c: c["build"]["runtime_input_binding"]["stop_projection"]["survivor_metadata"]["config.json"]["after"].update({"nlink": True}),
            "survivor-float": lambda r, c: c["build"]["runtime_input_binding"]["stop_projection"]["survivor_metadata"]["config.json"]["after"].update({"dev": float(os.makedev(259, 6))}),
            "top-bool": top_pid, "root-owner": anchor_owner, "reverse-range": reversed_range,
        }
        for label, mutate in cases.items():
            rootfs, contract = _runtime_evidence(repository, "builder-a", capsule)
            mutate(rootfs, contract)
            with self.subTest(label=label), self.assertRaises((RuntimeError, ValueError)):
                kernel_build._validate_runtime_evidence(rootfs, contract, capsule, repository=repository, builder="builder-a", expected_uid=os.getuid(), expected_gid=os.getgid())

