    def test_bound_accepted_tree_holds_files_and_all_directory_anchors(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            repository = Path(directory_name)
            final, receipt = self._publish_builder(repository, "builder-a")
            with proof_io.BoundAcceptedTree.open(
                final,
                receipt,
                allowed_files=kernel_build.PUBLIC_OUTPUT_FILES, expected_uid=os.geteuid(), expected_gid=os.getegid()
            ) as tree:
                manifest_descriptor = tree.descriptor("rpm-artifacts.json")
                original = proof_io._read_descriptor(manifest_descriptor)
                manifest = final / "rpm-artifacts.json"
                replacement = final / "replacement"
                replacement.write_bytes(b"{}\n")
                replacement.replace(manifest)
                self.assertEqual(
                    proof_io._read_descriptor(manifest_descriptor), original
                )
                with self.assertRaisesRegex(RuntimeError, "path identity|changed"):
                    tree.verify_coherent()

            final, receipt = self._republish_after_removing(repository, "builder-a")
            with proof_io.BoundAcceptedTree.open(
                final,
                receipt,
                allowed_files=kernel_build.PUBLIC_OUTPUT_FILES, expected_uid=os.geteuid(), expected_gid=os.getegid()
            ) as tree:
                injected = final / "rpmbuild/unexpected"
                injected.mkdir()
                injected.rmdir()
                with self.assertRaisesRegex(RuntimeError, "directory.*changed"):
                    tree.verify_coherent()

