    def test_bound_accepted_tree_closes_current_directory_on_listing_failure(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            repository = Path(directory_name)
            final, receipt = self._publish_builder(repository, "builder-a")
            (final / "unexpected").write_bytes(b"extra")

            def held_final_directories() -> list[str]:
                held: list[str] = []
                for entry in Path("/proc/self/fd").iterdir():
                    try:
                        target = os.readlink(entry)
                    except FileNotFoundError:
                        continue
                    if target == str(final):
                        held.append(target)
                return held

            self.assertEqual(held_final_directories(), [])
            with self.assertRaisesRegex(ReceiptError, "listing"):
                proof_io.BoundAcceptedTree.open(
                    final,
                    receipt,
                    allowed_files=kernel_build.PUBLIC_OUTPUT_FILES, expected_uid=os.geteuid(), expected_gid=os.getegid()
                )
            self.assertEqual(held_final_directories(), [])

            final, receipt = self._republish_after_removing(repository, "builder-a")
            (final / "unexpected").write_bytes(b"extra")
            with self.assertRaisesRegex(ReceiptError, "listing"):
                proof_io.BoundAcceptedTree.open(
                    final,
                    receipt,
                    allowed_files=kernel_build.PUBLIC_OUTPUT_FILES, expected_uid=os.geteuid(), expected_gid=os.getegid()
                )

            final, receipt = self._republish_after_removing(repository, "builder-a")
            final.chmod(0o777)
            with self.assertRaisesRegex(ReceiptError, "root.*metadata|commitment"):
                proof_io.BoundAcceptedTree.open(
                    final,
                    receipt,
                    allowed_files=kernel_build.PUBLIC_OUTPUT_FILES, expected_uid=os.geteuid(), expected_gid=os.getegid()
                )

    def _republish_after_removing(
        self, repository: Path, builder: str
    ) -> tuple[Path, Path]:
        builder_root = repository / "build/gate01" / builder
        for path in (builder_root / "kernel.receipt.json", builder_root / "kernel"):
            if path.is_dir():
                import shutil

                shutil.rmtree(path)
            else:
                path.unlink(missing_ok=True)
        return self._publish_builder(repository, builder)

