    def test_comparison_holds_both_builder_and_output_locks_through_receipt(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            repository = Path(directory_name)
            self._publish_builder(repository, "builder-a")
            self._publish_builder(repository, "builder-b")
            real_publish = proof_io.publish_evidence_file

            def publish(payload: bytes, **arguments: object) -> dict[str, object]:
                lock_paths = (
                    repository / "build/gate01/builder-a/kernel-build.lock",
                    repository / "build/gate01/builder-b/kernel-build.lock",
                    repository / "build/gate01/.kernel-rpm-comparison.lock",
                )
                descriptors = [os.open(path, os.O_RDWR) for path in lock_paths]
                try:
                    for descriptor in descriptors:
                        with self.assertRaises(BlockingIOError):
                            fcntl.flock(
                                descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB
                            )
                finally:
                    for descriptor in descriptors:
                        os.close(descriptor)
                return real_publish(payload, **arguments)  # type: ignore[arg-type]

            with mock.patch.object(
                kernel_build, "publish_evidence_file", side_effect=publish
            ):
                self.assertEqual(
                    kernel_build.run_comparison(repository)["verdict"], "pass"
                )

