    def test_meta_cleanup_attempts_store_capsule_and_tree_for_every_fault(self) -> None:
        class Capsule:
            def __init__(self, fail: bool, calls: list[str]) -> None:
                self.fail = fail
                self.calls = calls

            def close(self) -> None:
                self.calls.append("capsule")
                if self.fail:
                    raise OSError("capsule cleanup")

        for fault in ("store", "capsule", "tree"):
            calls: list[str] = []
            capsule = Capsule(fault == "capsule", calls)

            def remove_store(_store: object) -> None:
                calls.append("store")
                if fault == "store":
                    raise OSError("store cleanup")

            def remove_tree(_path: Path) -> None:
                calls.append("tree")
                if fault == "tree":
                    raise OSError("tree cleanup")

            with self.subTest(fault=fault), self.assertRaisesRegex(
                RuntimeError, "meta proof cleanup"
            ):
                kernel_build._cleanup_meta_resources(
                    object(),
                    capsule,
                    Path("/scoped/meta-runtime"),
                    remove_store=remove_store,
                    remove_tree=remove_tree,
                )
            self.assertEqual(calls, ["store", "capsule", "tree"])

