    def test_meta_runtime_setup_reports_cleanup_failure(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            parent = Path(directory_name)
            primary = OSError("injected chmod failure")
            remove = kernel_build._ScopedTemporaryTree.remove
            baseline = len(os.listdir("/proc/self/fd"))

            def fail_chmod(_path: Path, _mode: int) -> None:
                raise primary

            def failed_remove(tree) -> None:
                remove(tree)
                raise OSError("injected setup cleanup failure")

            with (
                mock.patch.object(
                    kernel_build._ScopedTemporaryTree,
                    "remove",
                    new=failed_remove,
                ),
                self.assertRaises(OSError) as caught,
            ):
                kernel_build._create_scoped_temporary_tree(
                    parent, set_mode=fail_chmod
                )
            self.assertIs(caught.exception, primary)
            self.assertIn("additional meta runtime setup cleanup failed", primary.__notes__)
            self.assertEqual(list(parent.iterdir()), [])
            self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)

    def test_meta_runtime_setup_rejects_pre_anchor_path_replacement(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            parent = Path(directory_name)

            def replace_after_create(path: Path, _mode: int) -> None:
                moved = path.with_name(f"{path.name}.escaped-original")
                path.rename(moved)
                path.mkdir(mode=0o700)

            with self.assertRaisesRegex(RuntimeError, "setup.*changed"):
                kernel_build._create_scoped_temporary_tree(
                    parent, set_mode=replace_after_create
                )
            self.assertEqual(list(parent.iterdir()), [])

