    def test_meta_cleanup_removes_held_runtime_after_path_replacement(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            parent = Path(directory_name)
            runtime = parent / ".kernel-meta-runtime"
            runtime.mkdir(mode=0o700)
            (runtime / "original").write_bytes(b"private scratch")
            anchor = kernel_build._ScopedTemporaryTree.open(runtime)
            moved = parent / ".kernel-meta-runtime.moved"
            runtime.rename(moved)
            runtime.mkdir(mode=0o700)
            (runtime / "replacement").write_bytes(b"replacement")
