    def test_scoped_tree_remove_never_follows_arbitrary_alias_stat_race(self) -> None:
        with tempfile.TemporaryDirectory() as directory_name:
            parent = Path(directory_name)
            runtime = parent / ".kernel-meta-runtime"
            runtime.mkdir(mode=0o700)
            (runtime / "owned-marker").write_bytes(b"owned material\n")
            unrelated = parent / "unrelated"
            unrelated.mkdir(mode=0o700)
            unrelated_marker = unrelated / "unrelated-marker"
            unrelated_marker.write_bytes(b"must survive\n")
            preexisting_derived = parent / ".kernel-meta-runtime.preexisting"
            preexisting_derived.mkdir(mode=0o700)
            derived_marker = preexisting_derived / "marker"
            derived_marker.write_bytes(b"also not owned\n")
            baseline = len(os.listdir("/proc/self/fd"))
            tree = kernel_build._ScopedTemporaryTree.open(runtime)
            arbitrary_alias = parent / "a-alias"
            saved_root = parent / "saved-root"
            runtime.rename(arbitrary_alias)
            real_stat = os.stat
            swapped = False

            def stat_then_swap(
                path: str | bytes | os.PathLike[str] | os.PathLike[bytes],
                *args: object,
                **kwargs: object,
            ) -> os.stat_result:
                nonlocal swapped
                result = real_stat(path, *args, **kwargs)
                if (
                    not swapped
                    and os.fsdecode(path) == arbitrary_alias.name
                    and kwargs.get("dir_fd") == tree._parent_descriptor
                ):
                    os.rename(
                        arbitrary_alias.name,
                        saved_root.name,
                        src_dir_fd=tree._parent_descriptor,
                        dst_dir_fd=tree._parent_descriptor,
                    )
                    os.rename(
                        unrelated.name,
                        arbitrary_alias.name,
                        src_dir_fd=tree._parent_descriptor,
                        dst_dir_fd=tree._parent_descriptor,
                    )
                    swapped = True
                return result

            with (
                mock.patch.object(kernel_build.os, "stat", side_effect=stat_then_swap),
                self.assertRaisesRegex(
                    RuntimeError, "meta cleanup path changed or removal failed"
                ),
            ):
                tree.remove()
            self.assertFalse(swapped)
            self.assertEqual(unrelated_marker.read_bytes(), b"must survive\n")
            self.assertEqual(derived_marker.read_bytes(), b"also not owned\n")
            self.assertTrue(arbitrary_alias.is_dir())
            self.assertEqual(list(arbitrary_alias.iterdir()), [])
            self.assertFalse(saved_root.exists())
            tree.remove()
            self.assertEqual(len(os.listdir("/proc/self/fd")), baseline)

    def test_public_cli_dispatches_run_compare_and_meta(self) -> None:
        with (
            mock.patch.object(kernel_build, "run_builder", return_value={"verdict": "pass"}) as run,
            mock.patch.object(kernel_build, "run_comparison", return_value={"verdict": "pass"}) as compare,
            mock.patch.object(kernel_build, "run_meta_requirements", return_value={"verdict": "pass"}) as meta,
            mock.patch.object(sys, "stdout", new_callable=io.StringIO) as output,
        ):
            self.assertEqual(main(["run", "--repo", "/repo", "builder-a"]), 0)
            self.assertEqual(main(["compare", "--repo", "/repo"]), 0)
            self.assertEqual(
                main(
                    [
                        "meta-requirements",
                        "--repo",
                        "/repo",
                        "--builder",
                        "builder-b",
                    ]
                ),
                0,
            )
            self.assertEqual([json.loads(line) for line in output.getvalue().splitlines()], [{"verdict": "pass"}, {"verdict": "pass"}])
        run.assert_called_once_with(Path("/repo"), "builder-a")
        compare.assert_called_once_with(Path("/repo"))
        meta.assert_called_once_with(Path("/repo"), "builder-b")


